return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Hindi','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-10 13:58+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'hi_IN','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" सहेजा गया।','"%1$s" created. %2$d template updated.'=>'"%1$s" बनाया गया। %2$d टेम्पलेट अपडेट किया गया।' . "\0" . '"%1$s" बनाया गया। %2$d टेम्पलेट अपडेट किए गए।','"%s" created.'=>'"%s" बनाया गया।','"product" (replaces "article")'=>'"उत्पाद" ("लेख" को बदलता है)','"Treat H2 as H1 equivalent" (Settings → SEO → Analysis): enable this when your theme renders the post title inside an H2 instead of an H1. The analyser promotes the first H2 to H1 so the score is not incorrectly penalised.'=>'"H2 को H1 के समकक्ष मानें" (सेटिंग्स → SEO → विश्लेषण): इसे सक्षम करें जब आपका थीम पोस्ट टाइटल को H2 के अंदर रेंडर करता है बजाय H1 के। विश्लेषक पहले H2 को H1 में प्रमोट करता है ताकि स्कोर गलत तरीके से दंडित न हो।','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d वर्ण — अच्छा, आदर्श %2$d से थोड़ा ऊपर लेकिन स्वीकृत %3$d-चर रेंज के भीतर। %4$s','%1$d chars — ideal length. %2$s'=>'%1$d वर्ण — आदर्श लंबाई। %2$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d वर्ण — संभवतः SERPs में कट गए हैं (%2$d से कम रखें)। %3$s','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d वर्ण — बहुत छोटा (लक्ष्य %2$d–%3$d के लिए)। %4$s','%1$d chars, %2$d words — good title.'=>'%1$d वर्ण, %2$d शब्द — अच्छा शीर्षक।','%1$d internal, %2$d external.'=>'%1$d आंतरिक, %2$d बाहरी।','%1$d of %2$d image(s) missing alt text.'=>'%1$d में से %2$d छवियों का ऑल्ट टेक्स्ट गायब है।','%1$d post tagged with _lf_lang = %2$s.'=>'%1$d पोस्ट _lf_lang = %2$s के साथ टैग किया गया।' . "\0" . '%1$d पोस्ट _lf_lang = %2$s के साथ टैग किया गया।','%1$d words — below recommended minimum of %2$d.'=>'%1$d शब्द — %2$d की अनुशंसित न्यूनतम से कम।','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d शब्द — बहुत पतली सामग्री। कम से कम %2$d शब्दों तक विस्तार करने पर विचार करें।','%d external link(s), no internal links.'=>'%d बाहरी लिंक, कोई आंतरिक लिंक नहीं।','%d external link(s), no internal links. Add internal links to related content.'=>'%d बाहरी लिंक, कोई आंतरिक लिंक नहीं। संबंधित सामग्री के लिए आंतरिक लिंक जोड़ें।','%d H1 tags found — a page should have exactly one H1.'=>'%d H1 टैग पाए गए — एक पृष्ठ में बिल्कुल एक H1 होना चाहिए।','%d image(s), all have alt text.'=>'%d छवियां, सभी के पास ऑल्ट टेक्स्ट है।','%d language not yet linked'=>'%d भाषा अभी तक लिंक नहीं है' . "\0" . '%d भाषाएं अभी तक लिंक नहीं हैं','%d link updated.'=>'%d लिंक अपडेट किया गया।' . "\0" . '%d लिंक अपडेट किए गए।','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'%d स्थानीय फ़ाइल स्वचालित रूप से नहीं हटाई जा सकी (DISALLOW_FILE_MODS सेट है)। इसे अपने सर्वर या WP-CLI के माध्यम से मैन्युअल रूप से हटा दें: wp language core uninstall <locale>' . "\0" . '%d स्थानीय फ़ाइलें स्वचालित रूप से नहीं हटाई जा सकीं (DISALLOW_FILE_MODS सेट है)। इन्हें अपने सर्वर या WP-CLI के माध्यम से मैन्युअल रूप से हटा दें: wp language core uninstall <locale>','%d locale file removed.'=>'%d स्थानीय फ़ाइल हटा दी गई।' . "\0" . '%d स्थानीय फ़ाइलें हटा दी गईं।','%d locale pack installed.'=>'%d लोकल पैक स्थापित।' . "\0" . '%d लोकल पैक स्थापित।','%d navigation reference updated.'=>'%d नेविगेशन संदर्भ अपडेट किया गया।' . "\0" . '%d नेविगेशन संदर्भ अपडेट किए गए।','%d part reference updated.'=>'%d भाग संदर्भ अपडेट किया गया।' . "\0" . '%d भाग संदर्भ अपडेट किए गए।','%d post'=>'%d पोस्ट' . "\0" . '%d पोस्ट','%d rule registered'=>'%d नियम पंजीकृत' . "\0" . '%d नियम पंजीकृत','%d words.'=>'%d शब्द।','%s Archive'=>'%s आर्काइव','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s सक्रिय है और पहले से ही Schema.org JSON-LD आउटपुट करता है। Lingua Forge ने अपने स्कीमा आउटपुट को अक्षम कर दिया है ताकि टकराव वाली ग्राफ़ से बचा जा सके। Open Graph के विपरीत — जहां LF दूसरे प्लगइन के आउटपुट पर og:locale जोड़ता है — स्कीमा को साफ़-सुथरे ढंग से पूरक नहीं किया जा सकता: डुप्लिकेट या ओवरलैपिंग JSON-LD ग्राफ़ मान्यकरण त्रुटियों का कारण बनते हैं। यदि आप चाहते हैं कि LF संरचित डेटा को संभाले, तो पहचाने गए प्लगइन में स्कीमा आउटपुट को अक्षम करें।','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s सक्रिय है और अपना स्वयं का साइटमैप बनाता है। वह साइटमैप LF से अलग है। दोनों को Google Search Console में जमा करना चाहिए: SEO प्लगइन साइटमैप आपके सामग्री को सूचीबद्ध करता है; LF साइटमैप बहुभाषी वैकल्पिक लिंक जोड़ता है। LF का साइटमैप स्वचालित रूप से robots.txt में घोषित किया जाता है।','(active)'=>'(सक्रिय)','(avg %.1f hits/block)'=>'(औसत %.1f हिट्स/ब्लॉक)','(avg %.1f hits/entry)'=>'(औसत %.1f हिट/प्रविष्टि) ','(classic theme)'=>'(क्लासिक थीम)','(disabled)'=>'(अक्षम) ','(FSE / block theme)'=>'(FSE / ब्लॉक थीम)','(no title) #%d'=>'(कोई शीर्षक नहीं) #%d','(partial)'=>'(आंशिक)','(server/FPM timeout still applies)'=>'(सर्वर/FPM टाइमआउट अभी भी लागू होता है)','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} में कोई प्रतिस्थापन योग्य लिंक नहीं था — जांच के लिए पुनः स्कैन करें)','.txt file(s) in the directory'=>'.txt फ़ाइल(ें) इस निर्देशिका में','/ 100'=>'/ 100','1 H1 ✓ — no H2 or H3 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — कोई H2 या H3 उप-शीर्षक नहीं मिले। H2 जोड़ने से संरचना में सुधार होता है।','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'1 H1 ✓ — कोई H2 उपशीर्षक नहीं (इस सामग्री प्रकार के लिए स्वीकार्य)।','1 H1 ✓ — no H2, but %d H3 subheading(s) found (e.g. accordion/details headers). Structure is acceptable.'=>'1 H1 ✓ — कोई H2 नहीं, लेकिन %d H3 उपशीर्षक पाए गए (जैसे कि अकॉर्डियन/विवरण हेडर)। संरचना स्वीकार्य है।','1 H1 ✓ — short content (%d paragraph(s)), subheadings not required.'=>'1 H1 ✓ — संक्षिप्त सामग्री (%d पैराग्राफ), उपशीर्षक आवश्यक नहीं।','1 H1 ✓, %1$d H2, %2$d H3.'=>'1 H1 ✓, %1$d H2, %2$d H3।','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>लिंगुआ फोर्ज:</strong> %1$d स्थानीयकृत टेम्प्लेट(स) &#8220;%2$s&#8221; थीम से डेटाबेस में संरक्षित हैं लेकिन वर्तमान में निष्क्रिय हैं। यदि आप उस थीम को पुनः सक्रिय करते हैं तो वे फिर से सक्रिय हो जाएंगे। अपनी अनुवादों को नई थीम पर ले जाने के लिए, उन्हें <strong>सेटिंग्स → लिंगुआ फोर्ज → राउटर → FSE स्कैफोल्ड</strong> के माध्यम से पुनः जेनरेट करें।','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> स्वचालित रूप से ठीक करने योग्य लिंक','<strong>{n}</strong> link(s) needing manual review'=>'मैनुअल समीक्षा की आवश्यकता वाले <strong>{n}</strong> लिंक','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> पुराना पथ(आम','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> टेम्पलेट समस्या(ए)','_lf_lang Coverage'=>'_lf_lang कवरेज','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'साइट रूट पर एक भौतिक robots.txt फ़ाइल मौजूद है। WordPress का वर्चुअल robots.txt — और LF का Sitemap: फ़िल्टर — बायपास हो गया है। LF का साइटमैप खोज इंजनों को घोषित नहीं किया गया है।','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'संकलित .mo फ़ाइलें ही स्वीकार की जाती हैं। फ़ाइल नाम {textdomain}-{locale}.mo के पैटर्न का पालन करना चाहिए। एक ही नाम की फ़ाइल अपलोड करने से वह प्रतिस्थापित हो जाएगी।','Access forbidden — your account may be suspended or the key lacks the required permissions.'=>'प्रवेश वर्जित — आपका खाता निलंबित हो सकता है या कुंजी आवश्यक अनुमतियों से वंचित है।','Action'=>'क्रिया','active'=>'सक्रिय','Active Languages'=>'सक्रिय भाषाएँ','Active languages'=>'सक्रिय भाषाएँ','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'सक्रिय भाषाएँ: प्रत्येक भाषा जोड़ें जिसे आप समर्थन करना चाहते हैं। प्रत्येक भाषा को एक URL उपसर्ग या उपडोमेन और एक hreflang टैग प्राप्त होता है पृष्ठ &lt;head&gt; में।','Active Plugins'=>'सक्रिय प्लगइन्स','Active preset'=>'सक्रिय पूर्वनिर्धारित','Active Provider'=>'सक्रिय प्रदाता','Active theme'=>'सक्रिय थीम','Active: %s.'=>'सक्रिय: %s।','Add entry'=>'प्रविष्टि जोड़ें','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'ड्राफ्ट में सुधार करने के लिए निर्देश जोड़ें — जैसे कि इसे छोटा बनाएं, निष्कर्ष अनुभाग जोड़ें, अधिक औपचारिक रजिस्टर का उपयोग करें, FAQ ब्लॉक शामिल करें…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'मसौदे में सुधार के लिए निर्देश जोड़ें — जैसे इसे छोटा बनाना, निष्कर्ष अनुभाग जोड़ना, अधिक औपचारिक रजिस्टर का उपयोग करना…','Add key →'=>'कुंजी जोड़ें →','Add new entry'=>'नई प्रविष्टि जोड़ें','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'प्रति पंक्ति एक शब्द जोड़ें। स्रोत शब्द और लक्ष्य रेंडरिंग दोनों आवश्यक हैं। भाषा जोड़ी तय करती है कि कौन से अनुवाद कार्य इस सीमा के अंतर्गत आते हैं। ','Add Sitemap directive to robots.txt'=>'robots.txt में Sitemap निर्देश जोड़ें','Add the following line to your robots.txt manually:'=>'अपने robots.txt में निम्नलिखित लाइन मैन्युअल रूप से जोड़ें:','Add WooCommerce product tags to Open Graph output'=>'Open Graph आउटपुट में WooCommerce उत्पाद टैग जोड़ें','Adds a link to the home page so visitors can browse in their language.'=>'ऐसे लिंक जोड़ता है ताकि आगंतुक अपनी भाषा में ब्राउज़ कर सकें।','Administrators only (manage_options)'=>'केवल व्यवस्थापक (प्रबंध_विकल्प)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'प्राथमिक भाषा बदलने के बाद, URL रूटिंग को अपडेट करने के लिए permalinks (सेक्शन नीचे) को फ्लश करें।','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'URL संरचना सेटिंग्स (पथ उपसर्ग ↔ उपडोमेन) बदलने के बाद, हमेशा सेटिंग्स → स्थायी लिंक पर जाएं और परिवर्तन सहेजें पर क्लिक करें ताकि पुनर्लेखन नियम साफ हो जाएं। ','AI analysis failed. Please try again.'=>'AI विश्लेषण विफल रहा। कृपया पुनः प्रयास करें।','AI Behaviour Preset'=>'एआई व्यवहार पूर्वनिर्धारित','AI cache cleared. %d entry was removed.'=>'AI कैश साफ़ कर दी गई। %d प्रविष्टि हटा दी गई।' . "\0" . 'AI कैश साफ़ कर दी गई। %d प्रविष्टियाँ हटा दी गईं।','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'एआई कैश: कैश किए गए एआई प्रतिक्रियाओं की सूची हिट गणनाओं के साथ। पूरे कैश या एकल पोस्ट की प्रविष्टियों को साफ करें। अनुवाद परिवर्तन का परीक्षण करने से पहले "साफ करें" का उपयोग करें — कैश किए गए परिणाम तब भी लौटाए जाते हैं जब आप एआई प्रीसेट या मॉडल बदलते हैं जब तक कि कैश प्रविष्टि हटा नहीं दी जाती। ','AI Configuration'=>'AI कॉन्फ़िगरेशन','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'एआई विशेषताएँ वैकल्पिक हैं। भाषा मार्गनिर्देशन, hreflang, भाषा स्विचर, और अनुवाद समूह प्रणाली बिना किसी प्रदाता के कॉन्फ़िगर किए काम करती हैं। ','AI Limits & Security'=>'AI सीमाएँ और सुरक्षा','AI Provider'=>'AI प्रदाता','AI provider returned an empty response.'=>'एआई प्रदाता ने खाली प्रतिक्रिया दी।','AI Recommendations'=>'AI सिफारिशें','AI returned an unexpected response format. Please try again.'=>'AI ने अप्रत्याशित प्रतिक्रिया प्रारूप लौटाया है। कृपया पुनः प्रयास करें।','AI translation and batch analysis may time out. Recommend 120s or more.'=>'AI अनुवाद और बैच विश्लेषण समय सीमा समाप्त हो सकता है। 120 सेकंड या अधिक की सिफारिश।','AI Usage'=>'एआई उपयोग','AI Usage & Cache'=>'AI उपयोग और कैश','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'120–160 वर्णों का लक्ष्य रखें। फॉलबैक के रूप में उपयोग करने के लिए खाली छोड़ दें।','All major search engines — Google, Bing, and Yandex — discover the sitemap automatically via the Sitemap: directive in robots.txt. No manual action is required. The buttons below send an immediate ping so the engine recrawls the sitemap now rather than waiting for its next scheduled robots.txt check.'=>'सभी प्रमुख खोज इंजन — Google, Bing, और Yandex — स्वचालित रूप से Sitemap: निर्देशिका के माध्यम से साइटमैप खोजते हैं। कोई मैनुअल कार्रवाई आवश्यक नहीं है। नीचे दिए गए बटन तुरंत पिंग भेजते हैं ताकि इंजन अब ही साइटमैप को पुनः क्रॉल कर सके।','All published posts have a _lf_lang value. No gaps detected.'=>'सभी प्रकाशित पोस्ट में _lf_lang मान है। कोई अंतराल नहीं पाया गया।','All time'=>'सभी समय','All types'=>'सभी प्रकार','Allow editors to lock individual blocks'=>'संपादकों को व्यक्तिगत ब्लॉक लॉक करने की अनुमति दें','Allow Gutenberg template-editing mode on post screens'=>'पोस्ट स्क्रीन पर Gutenberg टेम्प्लेट-एडिटिंग मोड की अनुमति दें','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'जब प्लगइन अनइंस्टॉल किया जाता है, तो भाषा असाइनमेंट, अनुवाद संबंध, मेटा विवरण, शब्दकोश, और अनुवाद स्मृति भी हटा दी जाती है।','Also generate meta description'=>'मेटा विवरण भी उत्पन्न करें','Alternative (server-side):'=>'वैकल्पिक (सर्वर-साइड):','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'सदैव केवल og:locale और og:locale:alternate का उत्सर्जन करें। जब कोई अन्य प्लगइन या थीम पूर्ण OG सेट को संभालता है तो इसका उपयोग करें।','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'सदैव पूर्ण OG + Twitter Card सेट का उत्सर्जन करें, चाहे अन्य प्लगइन्स कुछ भी करें। केवल तभी उपयोग करें जब कोई अन्य प्लगइन OG टैग्स का आउटपुट न करता हो।','An unknown error occurred.'=>'एक अज्ञात त्रुटि हुई।','Analyse'=>'विश्लेषण','Analyse all languages'=>'सभी भाषाओं का विश्लेषण करें','Analyse…'=>'विश्लेषण करें…','Analysis'=>'विश्लेषण','Analysis request failed. Please try again.'=>'विश्लेषण अनुरोध विफल रहा। कृपया पुनः प्रयास करें।','Analyzing…'=>'विश्लेषण हो रहा है…','and'=>'और','Anthropic (Claude)'=>'एंथ्रोपिक (क्लोड)','Anthropic Console'=>'एंथ्रोपिक कंसोल','any'=>'कोई भी','API calls saved by cache'=>'कैश द्वारा सहेजी गई API कॉल्स ','API Key'=>'एपीआई कुंजी','API Keys'=>'एपीआई कुंजी','API Keys Tab'=>'API कुंजी टैब ','API Response Cache'=>'API प्रतिक्रिया कैश ','API Response Cache setting saved.'=>'API प्रतिक्रिया कैश सेटिंग सहेजी गई।','Appends the following line to your existing robots.txt: %s'=>'आपके मौजूदा robots.txt में निम्नलिखित लाइन जोड़ता है: %s','Applied ✓'=>'लागू ✓','Apply failed — please try again.'=>'लागू करने में असफल — कृपया पुनः प्रयास करें।','Apply to all language versions'=>'सभी भाषा संस्करणों पर लागू करें','Apply to Block'=>'ब्लॉक पर लागू करें','Apply to Editor'=>'संपादक में लागू करें','Apply to Footnote'=>'टिप्पणी पर लागू करें','Apply to Meta Description'=>'मेटा विवरण पर लागू करें','Apply translation'=>'अनुवाद लागू करें','Applying…'=>'लागू किया जा रहा है…','Approximate size'=>'अनुमानित आकार','Archive'=>'आर्काइव','Archive: %s'=>'आर्काइव: %s','Article / WebPage'=>'लेख / वेबपृष्ठ','Article / WebPage — all singular posts and pages'=>'लेख / वेबपृष्ठ — सभी एकवचन पोस्ट और पृष्ठ','Authors and above (edit_published_posts)'=>'लेखक और ऊपर (संपादित_प्रकाशित_पोस्ट)','Auto (recommended)'=>'स्वचालित (सिफारिश की गई)','Auto-detect assigns: WooCommerce products → Product profile; the static front page → Landing profile; everything else → Blog profile. Choose a specific profile to override this for all posts.'=>'ऑटो-डिटेक्ट असाइन करता है: WooCommerce उत्पाद → उत्पाद प्रोफ़ाइल; स्थैतिक होमपेज → लैंडिंग प्रोफ़ाइल; बाकी → ब्लॉग प्रोफ़ाइल। इस पर सभी पोस्ट के लिए एक विशिष्ट प्रोफ़ाइल चुनें।','Auto-detected for the static front page; can be selected manually. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 10 pts · Images 15 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 150, fails below 60; H2 and internal links optional.'=>'स्थैतिक होमपेज के लिए ऑटो-डिटेक्ट किया गया; मैनुअल रूप से चुना जा सकता है। शीर्षक 20 अंक · मेटा विवरण 30 अंक · शब्द गणना 15 अंक · शीर्षक 10 अंक · छवियां 15 अंक · लिंक 0 अंक। शीर्षक SERP सीमा 70 वर्ण; शब्द गणना 150 से नीचे चेतावनी, 60 से नीचे असफल; H2 और आंतरिक लिंक वैकल्पिक।','Auto-detected for WooCommerce products. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 5 pts · Images 20 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 80, fails below 40; H2 and internal links optional.'=>'WooCommerce उत्पादों के लिए ऑटो-डिटेक्ट किया गया। शीर्षक 20 अंक · मेटा विवरण 30 अंक · शब्द गणना 15 अंक · शीर्षक 5 अंक · छवियां 20 अंक · लिंक 0 अंक। शीर्षक SERP सीमा 70 वर्ण; शब्द गणना 80 से नीचे चेतावनी, 40 से नीचे असफल; H2 और आंतरिक लिंक वैकल्पिक।','Available models reference'=>'उपलब्ध मॉडल संदर्भ','avg'=>'औसत','Batch Analysis'=>'बैच विश्लेषण','Behavior'=>'व्यवहार','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'व्यवहार: एआई प्रीसेट चुनें (शाब्दिक, संतुलित, रचनात्मक), साइट-व्यापी कस्टम प्रॉम्प्ट निर्देश जोड़ें, स्वचालित पोस्ट-सहेजने अनुवाद को सक्षम या अक्षम करें, और अनुवाद स्मृति को कॉन्फ़िगर करें। ','Block Content'=>'ब्लॉक सामग्री','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'जब वर्तमान पृष्ठ अपनी स्रोत भाषा में दिखाया जा रहा हो क्योंकि आगंतुक की भाषा के लिए कोई अनुवाद मौजूद नहीं है, तो यह विनम्र सूचना दिखाता है। यह Lingua Forge राउटर के LINGUAFORGE_LANG_FALLBACK_ACTIVE सिग्नल द्वारा संचालित है — जब अनुरोध क्षेत्र के लिए कोई अनुवाद मौजूद हो तो कुछ भी नहीं उत्सर्जित करता है।','Block Editor'=>'ब्लॉक संपादक','block keywordfallback'=>'फॉलबैक','block keywordi18n'=>'i18n','block keywordlanguage'=>'भाषा','block keywordlinguaforge'=>'लिंगुआ फोर्ज','block keywordtranslation'=>'अनुवाद','Block locking'=>'ब्लॉक लॉकिंग','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'कस्टम पोस्ट टाइप्स के लिए पंजीकृत ब्लॉक पैटर्न। भाषा संस्करण बनाने के लिए ट्रांसलेट बटन का उपयोग करें। अनुवादित सामग्री यहाँ सहेजी जाती है और ब्लॉक संपादक पैटर्न इंसर्टर से किसी भी CPT पोस्ट में कॉपी की जा सकती है या एक सिंक्ड पैटर्न (रीयूज़ेबल ब्लॉक) के लिए प्रारंभिक बिंदु के रूप में इस्तेमाल की जा सकती है।','block titleMissing Translation Notice'=>'अनुवाद अनुपस्थित सूचना','Block translation reuses'=>'ब्लॉक अनुवाद पुन: उपयोग ','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Glossary edits and Compliance preset changes automatically invalidate affected cached translations.'=>'ब्लॉक-स्तरीय अनुवाद कैश पोस्ट के बीच साझा किया गया। सक्षम होने पर, समान ब्लॉक (समान मार्कअप, भाषा जोड़ी, और शब्दावली) को फिर से AI को कॉल किए बिना मेमोरी से सेवा दी जाती है। शब्दावली संपादन और अनुपालन पूर्वनिर्धारित परिवर्तन स्वचालित रूप से प्रभावित कैश्ड अनुवादों को अमान्य कर देते हैं।','Blog / Editorial'=>'ब्लॉग / संपादकीय','Blog / Editorial (default)'=>'ब्लॉग / संपादकीय (डिफ़ॉल्ट)','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'ब्लॉग पोस्ट को Article के रूप में उपयोग करता है; सभी अन्य पोस्ट प्रकार और पृष्ठ WebPage का उपयोग करते हैं। इसमें शीर्षक, विवरण, inLanguage, url, प्रकाशित तिथि, संशोधित तिथि, छवि, और प्रकाशक शामिल हैं।','Browser language redirect'=>'ब्राउज़र भाषा पुनः निर्देशित','Built-in preset instructions:'=>'इन-बिल्ट प्रीसेट निर्देश:','Bulletize (•-prefixed)'=>'बुलेट करें (•-प्रारंभिक)','cached'=>'कैश्ड','Cached API responses'=>'कैश किए गए API प्रतिक्रियाएँ ','Cached block translations'=>'कैश किए गए ब्लॉक अनुवाद ','Cancel'=>'रद्द करें','Cannot determine target language from slug.'=>'टग से लक्ष्य भाषा निर्धारित नहीं की जा सकी।','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'उत्पाद %1$d पर लिख नहीं सकता: यह अनुवादित संस्करण है (भाषा: %2$s)%3$s। संचालनात्मक डेटा (मूल्य, स्टॉक, SKU, आयाम) स्रोत उत्पाद पर अपडेट किया जाना चाहिए। स्रोत उत्पाद ID को हल करने के लिए: GET /wp-json/lingua-forge/v1/post/%4$d/translations','Canonical tag'=>'कैनोनिकल टैग','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'साइट कितनी AI उपयोग कर सकती है इसकी सीमा निर्धारित करें और कौन से उपयोगकर्ता भूमिकाएँ भुगतान किए गए AI कॉल कर सकती हैं, इसे प्रतिबंधित करें। यह प्रति-उपयोगकर्ता दर सीमा (30 अनुरोध / मिनट, हार्डकोडेड) के ऊपर बैठता है जो पहले से ही एकल-उपयोगकर्ता रनवे लूप से सुरक्षा करता है।','Cart'=>'कार्ट','chars'=>'अक्षर','Check your account, billing, or remaining credits directly on the provider console:'=>'अपने खाते, बिलिंग, या शेष क्रेडिट्स को सीधे प्रदाता कंसोल पर जांचें:','Checkout'=>'चेकआउट','Chunk translated'=>'खंड का अनुवाद किया गया','Chunk translated to:'=>'अनुवादित खंड:','Clear'=>'साफ़ करें','Clear All'=>'सभी साफ़ करें','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'क्या सभी कैश्ड AI परिणामों को साफ़ कर दें? भविष्य की अनुरोध नई API कॉल ट्रिगर करेंगी जब तक कि कैश पुनः बन न जाए।','Clear API Response Cache'=>'API प्रतिक्रिया कैश साफ़ करें ','Clear Debug Files'=>'डिबग फ़ाइलें साफ़ करें','Clear hints'=>'संकेत साफ़ करें','Clear input'=>'इनपुट साफ़ करें','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'संपूर्ण अनुवाद स्मृति साफ़ करें? भविष्य के अनुवाद उन्हें पुनः बनाना शुरू कर देंगे।','Clear Translation Memory'=>'अनुवाद स्मृति साफ़ करें','Close'=>'बंद करें','Close language panel'=>'भाषा पैनल बंद करें ','Close popover'=>'पॉपओवर बंद करें','Compatibility'=>'अनुकूलता','Compliance Preset'=>'अनुपालन पूर्वसेट','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'AI-आधारित सिफारिशों को सक्षम करने के लिए सेटिंग्स → API Keys में एक AI प्रदाता कॉन्फ़िगर करें।','Configure hreflang, Open Graph, Schema.org, sitemaps, and social sharing for every language on your site. Each section below handles one aspect of multilingual SEO.'=>'अपनी साइट पर हर भाषा के लिए hreflang, ओपन ग्राफ, Schema.org, साइटमैप्स, और सोशल शेयरिंग कॉन्फ़िगर करें। नीचे प्रत्येक अनुभाग बहुभाषी SEO के एक पहलू को संभालता है।','Configured'=>'कॉन्फ़िगर किया गया','Contact Form 7 (wpcf7_contact_form) is excluded automatically. Add any other third-party post types whose content should not be language-filtered, one per line or comma-separated.'=>'Contact Form 7 (wpcf7_contact_form) स्वचालित रूप से बाहर है। कोई भी अन्य थर्ड-पार्टी पोस्ट प्रकार जोड़ें जिनका सामग्री भाषा-फ़िल्टर नहीं किया जाना चाहिए, एक प्रति पंक्ति या कॉमा से अलग।','Content generated'=>'सामग्री बनाई गई','Content Generator'=>'सामग्री जनरेटर','Content profiles and weights'=>'सामग्री प्रोफाइल और वज़न','Content ready'=>'सामग्री तैयार है','Contributors and above — default (edit_posts)'=>'योगदानकर्ता और ऊपर — डिफ़ॉल्ट (संपादित_पोस्ट)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'यह नियंत्रित करें कि कितना कंटेंट AI को भेजा जाए और प्रतिक्रिया कितनी बड़ी हो सकती है। यदि बड़ी पृष्ठें कट रही हैं तो इन मानों को बढ़ाएँ; लागत कम करने के लिए इन्हें घटाएँ।','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'AI कंटेंट जनरेटर सुविधा के लिए टोकन बजट और इनपुट सीमाओं को नियंत्रित करता है। अंतर्निहित डिफ़ॉल्ट का उपयोग करने के लिए फ़ील्ड खाली छोड़ें।','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'जब व्यवस्थापक प्लगइन को Plugins → Installed Plugins → Delete से हटाता है तो क्या होता है, इसे नियंत्रित करता है। प्लगइन सेटिंग्स और AI कैशेस हमेशा हटा दी जाती हैं। भाषा असाइनमेंट और अनुवाद संबंध डिफ़ॉल्ट रूप से रखे जाते हैं ताकि अनजाने में अनइंस्टॉल या पुनः इंस्टॉल करने पर वे वहीं से शुरू हो सकें।','Conversational'=>'संवादात्मक','Copied ✓'=>'कॉपी किया ✓','Copied!'=>'कॉपी की गई!','Copy'=>'कॉपी','Copy and paste into a GitHub issue or support request.'=>'GitHub मुद्दे या समर्थन अनुरोध में कॉपी और पेस्ट करें।','Copy failed — please copy the URL manually.'=>'कॉपी विफल रहा — कृपया URL को मैन्युअल रूप से कॉपी करें।','Copy markup'=>'मार्कअप कॉपी करें','Copy system info'=>'सिस्टम जानकारी कॉपी करें','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'सक्रिय URL को क्लिपबोर्ड पर कॉपी करें। सफलता पर "लिंक कॉपी किया" टोस दिखाता है।','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'परिणाम को कॉपी करें और जहां आवश्यक हो वहां चिपकाएं (जैसे सीधे फुटनोट फ़ील्ड में)।','Copy to safe storage'=>'सुरक्षित संग्रह में कॉपी करें','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'कॉपी/नेटिव/ऑटो JS क्रियाएँ: LF के सोशल-शेयर.js द्वारा संभाली गईं','Could not add entry: source term and target term are required.'=>'प्रविष्टि जोड़ने में असमर्थ: स्रोत शब्द और लक्ष्य शब्द आवश्यक हैं।','Could not copy the file. Check that the uploads folder is writable.'=>'फ़ाइल कॉपी नहीं कर सका। जांचें कि अपलोड फ़ोल्डर लिखने योग्य है या नहीं।','Could not instantiate the provider.'=>'प्रदाता को स्थापित नहीं किया जा सका।','Could not save the file. Check that the uploads folder is writable.'=>'फ़ाइल सहेज नहीं सकी। जांचें कि अपलोड फ़ोल्डर लिखने योग्य है या नहीं।','Could not save the glossary entry.'=>'शब्दावली प्रविष्टि सहेजने में असमर्थ।','Could not write to robots.txt. Check file permissions.'=>'robots.txt में लिखने में असमर्थ। फ़ाइल अनुमतियों की जाँच करें।','CPT Block Patterns'=>'CPT ब्लॉक पैटर्न','Create'=>'बनाएँ','Create missing'=>'गुम हुई चीज़ बनाएँ','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'पोस्ट प्रकार "%s" के लिए अनुवाद बनाना एक सक्रिय एकीकरण की आवश्यकता है। कृपया सुनिश्चित करें कि आवश्यक एकीकरण स्थापित और सक्रिय है।','Creating…'=>'बनाया जा रहा है…','Creative / Marketing'=>'रचनात्मक / विपणन','Creative / Marketing instructions'=>'रचनात्मक / विपणन निर्देश','Current content (will be overwritten)'=>'वर्तमान सामग्री (ओवरराइट की जाएगी)','Current status'=>'वर्तमान स्थिति','Current title'=>'वर्तमान शीर्षक','Current: {current}'=>'वर्तमान: {current}','Currently emitting'=>'वर्तमान में उत्सर्जित','Currently inherited from the %s constant. Selecting a value here will override it.'=>'वर्तमान में %s स्थिरांक से विरासत में मिला है। यहाँ मान चुनने से यह ओवरराइड हो जाएगा।','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'वर्तमान में उन पोस्ट के लिए छोड़ दिया गया है जो ब्लॉक-टिप्पणी विशेषता प्लेसहोल्डर (wp:details सारांश क्षेत्र आदि) का उपयोग करते हैं — वे मौजूदा एकल-आह्वान अनुवाद पथ पर जाते हैं।','Currently:'=>'वर्तमान में:','Custom'=>'कस्टम','Custom tables — LF post-meta filters do not affect orders.'=>'कस्टम टेबल — LF पोस्ट-मेटा फ़िल्टर आदेशों को प्रभावित नहीं करते।','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'दैनिक AI कोटा पूरा हो गया (%1$d अनुरोध)। यह %2$s UTC पर रीसेट होता है।','Daily quota'=>'दैनिक कोटा','Daily request limit'=>'दैनिक अनुरोध सीमा','Danger Zone'=>'खतरे का क्षेत्र','Debug Files'=>'डिबग फ़ाइलें','Debug files cleared. %d file was removed.'=>'डिबग फ़ाइलें साफ़ कर दी गईं। %d फ़ाइल हटा दी गई।' . "\0" . 'डिबग फ़ाइलें साफ़ कर दी गईं। %d फ़ाइलें हटा दी गईं।','Debug Info'=>'डिबग जानकारी','Debug logging'=>'डिबग लॉगिंग','Debug logging disabled.'=>'डिबग लॉगिंग अक्षम।','Debug logging enabled.'=>'डिबग लॉगिंग सक्षम।','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'डिबग: एआई प्रॉम्प्ट और API प्रतिक्रियाओं को एक स्थानीय फ़ाइल में कैप्चर करने के लिए डिबग लॉग सक्षम करें। समस्या निवारण के बाद अक्षम करें — डिबग मोड हर एआई अनुरोध पर एक फ़ाइल लिखता है। ','Default OG image'=>'डिफ़ॉल्ट OG छवि','Default profile'=>'डिफ़ॉल्ट प्रोफ़ाइल','Delete'=>'हटाएँ','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'डिबग निर्देशिका में सभी .txt फ़ाइलें हटाएँ? निर्देशिका स्वयं बनी रहेगी ताकि भविष्य में डिबग लिखावट साफ़ तरीके से हो सके।','Delete all files for this override (both .mo and .po)?'=>'क्या इस ओवरराइड के लिए सभी फ़ाइलें हटा दी जाएं (दोनों .mo और .po)?','Delete content data on uninstall'=>'अस्थायी रूप से सामग्री डेटा हटाएँ','Delete this glossary entry?'=>'क्या आप इस शब्दावली प्रविष्टि को हटाना चाहते हैं?','Describe what to write — topic, key points, structure…'=>'क्या लिखना है — विषय, मुख्य बिंदु, संरचना…','Destructive action — read before proceeding'=>'विनाशकारी क्रिया — आगे बढ़ने से पहले पढ़ें','Details ↗'=>'विवरण ↗','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'रuntime पर सक्रिय SEO प्लगइन्स (Yoast, Rank Math, आदि) का पता लगाएँ। जब कोई अन्य प्लगइन पहले से ही पूरा OG सेट आउटपुट कर रहा हो, तो केवल og:locale + og:locale:alternate ही उत्सर्जित करें; जब कोई भी नहीं पाया जाता है, तो पूरा सेट आउटपुट करें।','Directory'=>'डायरेक्टरी','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'केवल हेडलेस साइटों या पूरी तरह से कस्टम hreflang कार्यान्वयन के लिए अक्षम करें। जब अक्षम किया जाता है, तो LF अब WordPress कोर canonical टैग नहीं हटाता और SEO-Plugin hreflang आउटपुट को भी नहीं दबाता।','Disabled'=>'अक्षम','Disabled (by setting)'=>'सेटिंग द्वारा अक्षम','Disabled (mode setting)'=>'मोड सेटिंग द्वारा अक्षम','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'पहले से ही LF-सामाजिक-शेयर mu-plugin इस सुविधा को प्रदान कर रहा है, इसलिए इसे अक्षम किया गया है।','DISALLOW_FILE_MODS is set.'=>'DISALLOW_FILE_MODS सेट है।','Display'=>'प्रदर्शन','Displays the Lingua Forge language switcher.'=>'लिंगुआ फोर्ज भाषा स्विचर प्रदर्शित करता है।','Do not output any OG tags.'=>'कोई OG टैग आउटपुट न करें।','Documentation'=>'दस्तावेज़ीकरण ','Done'=>'पूर्ण','Done — {done} of {total} post(s) fixed.'=>'पूरा — {done} में से {total} पोस्ट ठीक की गई।','Down'=>'नीचे','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'WordPress.org से सीधे वर्डप्रेस कोर भाषा पैक डाउनलोड और स्थापित करें। एक बार स्थापित हो जाने के बाद, लोकल URL रूटिंग और AI अनुवाद कार्यप्रवाह के लिए उपलब्ध हो जाती है। उपलब्ध भाषाओं की सूची आवश्यकतानुसार प्राप्त की जाती है — नीचे दिए गए बटन पर क्लिक करें।','Dropdown direction'=>'ड्रॉपडाउन दिशा','Each metric yields one of four statuses: ok (full weight), warn (50 % of weight), fail (0), or info (0, no penalty). A score ≥ 80 is green, 50–79 amber, below 50 red.'=>'प्रत्येक मेट्रिक चार में से एक स्थिति देता है: ठीक (पूर्ण वज़न), चेतावनी (वज़न का 50%), असफल (0), या जानकारी (0, कोई दंड नहीं)। स्कोर ≥ 80 हरा है, 50–79 अम्बर, 50 से नीचे लाल।','Each post is scored 0–100 from six rule-based metrics: title, meta description, word count, heading structure, image alt coverage, and internal links. Ten points are always awarded for reading time (informational only). The remaining 90 points are distributed across the other metrics with weights that vary by content profile (see below).'=>'प्रत्येक पोस्ट का स्कोर 0–100 है, छह नियम-आधारित मेट्रिक्स से: शीर्षक, मेटा विवरण, शब्द गणना, शीर्षक संरचना, छवि विकल्प कवरेज, और आंतरिक लिंक। पढ़ने के समय के लिए दस अंक हमेशा दिए जाते हैं (केवल जानकारी के लिए)। शेष 90 अंक अन्य मेट्रिक्स में वितरित किए जाते हैं, जिनका वज़न सामग्री प्रोफ़ाइल के अनुसार भिन्न होता है (नीचे देखें)।','edit'=>'संपादित करें','Editors and above (edit_others_posts)'=>'संपादक और ऊपर (अन्य_पोस्ट_संपादित करें)','Enable API response caching'=>'API प्रतिक्रिया कैशिंग सक्षम करें ','Enable block-level translation cache reuse across posts'=>'ब्लॉक-स्तर अनुवाद कैश पुन: उपयोग को पोस्ट के बीच सक्षम करें','Enable Social Share URL rewriting for Social Icons blocks'=>'सामाजिक आइकन ब्लॉकों के लिए सोशल शेयर URL पुनर्लेखन सक्षम करें','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'जब आपका थीम पोस्ट शीर्षक को H2 के रूप में प्रस्तुत करता है तो सक्षम करें (कुछ ब्लॉक थीम में सामान्य)। विश्लेषक रेंडर किए गए पृष्ठ को लाता है और यदि यह H1 नहीं पाता है लेकिन H2 पाता है, तो यह पहले H2 को H1 में प्रमोट करता है ताकि स्कोरिंग के लिए।','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'कम से कम एक एआई प्रदाता के लिए अपनी API कुंजी दर्ज करें। कुंजी AES-256-GCM का उपयोग करके विशिष्ट साइट रहस्य (LINGUAFORGE_SECRET) के साथ विश्राम में एन्क्रिप्ट की जाती है। बिना पहले रहस्य को घुमाए डेटाबेस निर्यात साझा न करें। ','Environment'=>'पर्यावरण','environment variable'=>'पर्यावरण चर','Error'=>'त्रुटि','Every time a post is analysed the score is stored in post meta. The post list Lang column shows a colour-coded "SEO N" badge for any post that has been analysed at least once. When two scores are stored a delta indicator (↑N / ↓N) shows the change since the previous run.'=>'हर बार जब पोस्ट का विश्लेषण किया जाता है, तो स्कोर पोस्ट मेटा में संग्रहित किया जाता है। पोस्ट सूची का भाषा कॉलम एक रंग-कोडित "SEO N" बैज दिखाता है किसी भी पोस्ट के लिए जिसे कम से कम एक बार विश्लेषित किया गया हो। जब दो स्कोर संग्रहित होते हैं, तो एक डेल्टा संकेतक (↑N / ↓N) पिछले रन से परिवर्तन दिखाता है।','Exactly one H1 is required. The H1 is normally the post title rendered by the theme — it is read from the live rendered page when possible, and from post content as a fallback.'=>'सटीक रूप से एक H1 आवश्यक है। H1 सामान्यतः थीम द्वारा रेंडर किया गया पोस्ट टाइटल होता है — इसे लाइव रेंडर किए गए पेज से पढ़ा जाता है जब संभव हो, और पोस्ट सामग्री से एक बैकअप के रूप में।','Exclude from navigation menus'=>'नेविगेशन मेनू से बाहर करें','Exclude from routing'=>'राउटिंग से बाहर करें','Exclude this post type from language routing — its posts will no longer appear here or receive _lf_lang. This cannot be undone automatically.'=>'इस पोस्ट प्रकार को भाषा राउटिंग से बाहर करें — इसके पोस्ट अब यहां नहीं दिखेंगे या _lf_lang प्राप्त नहीं करेंगे। इसे स्वचालित रूप से वापस नहीं किया जा सकता।','Exclude this post type from language routing? Its posts will no longer appear in this list or receive _lf_lang. You can reverse this in Settings → Router → Query Filter Exclusions.'=>'क्या आप इस पोस्ट प्रकार को भाषा राउटिंग से बाहर करना चाहते हैं? इसके पोस्ट अब इस सूची में नहीं दिखेंगे या _lf_lang प्राप्त नहीं करेंगे। आप इसे सेटिंग्स → राउटर → क्वेरी फ़िल्टर बहिष्कार में उलट सकते हैं।','excluded from routing'=>'राउटिंग से बाहर किया गया','Excluded post types'=>'बहिष्कृत पोस्ट प्रकार','Excluding…'=>'बहिष्कृत कर रहा है…','Expand'=>'विस्तार करें','Expected: {expected}'=>'अपेक्षित: {expected}','External share services'=>'बाहरी शेयर सेवाएँ','Extra guidance — tone, style, constraints, target audience…'=>'अतिरिक्त मार्गदर्शन — टोन, शैली, प्रतिबंध, लक्षित दर्शक…','Extra guidance — tone, style, constraints…'=>'अतिरिक्त मार्गदर्शन — टोन, शैली, प्रतिबंध…','Failed to save exclusion.'=>'बहिष्करण सहेजने में विफल।','Failed. Please try again.'=>'असफल। कृपया पुनः प्रयास करें।','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'जब किसी पृष्ठ में फीचर्ड इमेज, साइट लोगो, या साइट आइकन नहीं होता है, तोFallback छवि URL का उपयोग किया जाता है। यह सामाजिक पूर्वावलोकनों में आर्काइव, ब्लॉग सूचकांक, और किसी भी सिंगल पृष्ठ के लिए दिखाया जाता है जिसमें थंबनेल नहीं होता।','Feature'=>'विशेषता','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'विशेषताएँ दो स्तरों में समूहित हैं। प्रत्येक स्तर और प्रदाता के लिए सटीक मॉडल पहचानकर्ता दर्ज करें। एक फ़ील्ड खाली छोड़ें ताकि डिफ़ॉल्ट का उपयोग हो सके। केवल सक्रिय प्रदाता के मॉडल रनटाइम पर कॉल किए जाते हैं — यदि आप स्विच करने की योजना बना रहे हैं तो अन्य को पहले से कॉन्फ़िगर करें।','File copied to safe storage successfully.'=>'सुरक्षित संग्रह में फ़ाइल सफलतापूर्वक कॉपी की गई।','File modifications are disabled (DISALLOW_FILE_MODS).'=>'फ़ाइल संशोधन अक्षम हैं (DISALLOW_FILE_MODS)।','Files'=>'फ़ाइलें','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'फ़ाइलें नीचे दिए गए निर्देशिका में land करती हैं। अनुवाद संबंधी मुद्दों का निदान करने के लिए उपयोगी — जब आप आवश्यक हो तो बंद कर दें ताकि फ़ाइलें जमा न हों। आप इसे wp-config.php से भी नियंत्रित कर सकते हैं `define( \'LINGUAFORGE_AI_DEBUG\', true );` के साथ, जो टॉगल को ओवरराइड करता है।','Filter'=>'फ़िल्टर','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'भाषा और पोस्ट प्रकार द्वारा फ़िल्टर करें, अपने सामग्री को ब्राउज़ करें, और किसी भी आइटम पर Analyze पर क्लिक करें ताकि नियम-आधारित SEO ऑडिट चलाया जा सके — शीर्षक की लंबाई, मेटा विवरण, शब्द गणना, शीर्षक संरचना, छवि ऑल्ट कवरेज, और आंतरिक लिंक।','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'डिबग आउटपुट को एक गैर-सार्वजनिक स्थान पर पुनर्निर्देशित करने के लिए linguaforge_debug_dir के साथ फ़िल्टर करें।','Finding'=>'खोज','Fix'=>'ठीक करें','Fix All'=>'सभी ठीक करें','Fix all links'=>'सभी लिंक ठीक करें','Fix all parts'=>'सभी भागों को ठीक करें','Fix Links'=>'लिंक ठीक करें','Fix Nav'=>'नेविगेशन ठीक करें','Fix Parts'=>'भाग ठीक करें','Fix Template'=>'टेम्पलेट ठीक करें','Fixing {n} / {total}…'=>'{n} / {total} को ठीक कर रहे हैं…','Fixing…'=>'ठीक किया जा रहा है…','Flush Permalink Rules'=>'Permalink नियमों को फ्लश करें','Flush Permalinks'=>'Permalinks को फ्लश करें','Flush Sitemap Cache'=>'साइटमैप कैश साफ़ करें','Footnote Content'=>'टिप्पणी सामग्री','footnote(s) translated — applied together with content.'=>'अनुवादित फुटनोट(s) — सामग्री के साथ लागू किया गया।','Footnotes'=>'फुटनोट','Footnotes payload (advanced)'=>'फुटनोट्स पेलोड (उन्नत)','Forbidden'=>'प्रतिबंधित','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'wp-config.php में LINGUAFORGE_AI_DEBUG स्थिरांक द्वारा जबरदस्ती बंद। इस टॉगल को नियंत्रित करने के लिए उस लाइन को हटा दें।','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'wp-config.php में LINGUAFORGE_AI_DEBUG स्थिरांक द्वारा जबरदस्ती चालू। इस टॉगल को नियंत्रित करने के लिए उस लाइन को हटा दें।','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'अगली अनुरोध पर साइटमैप को पुनः जेनरेट करने के लिए मजबूर करता है। बड़े पैमाने पर आयात या अनुवाद संबंधों को मैनुअल रूप से संपादित करने के बाद उपयोग करें।','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'<strong>{total}</strong> में से <strong>{scanned}</strong> स्कैन किए गए पोस्ट के बीच {parts} पाया गया।','From'=>'से','Front Page'=>'मुखपृष्ठ','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'FSE स्थानीयकरण: इस टैब से सीधे फुल साइट संपादन टेम्प्लेट और टेम्प्लेट भागों में स्कैफ़ोल्ड, अनुवाद, और लिंक सुधारें। ','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'सक्रिय थीम से बीजित FSE टेम्प्लेट। साइट संपादक में बनाएं और कस्टमाइज़ करें।','Full'=>'पूर्ण','Full Article'=>'पूर्ण लेख','Full post'=>'पूरा पोस्ट','Full-page Translation, Content Generator (mid-tier models are fully sufficient)'=>'पूर्ण-पृष्ठ अनुवाद, सामग्री निर्माता (मध्यम स्तर के मॉडल पूरी तरह पर्याप्त हैं)','General'=>'सामान्य','Generate'=>'सृजन करें','Generate Content'=>'सामग्री उत्पन्न करें','Generate content…'=>'सामग्री उत्पन्न करें…','Generate Excerpt'=>'अंश उत्पन्न करें','Generate Meta Description'=>'मेटा विवरण उत्पन्न करें','Generate the multilingual sitemap at /lf-sitemap.xml'=>'बहुभाषी साइटमैप /lf-sitemap.xml पर जेनरेट करें','Generated Content'=>'निर्मित सामग्री','Generated meta description'=>'निर्मित मेटा विवरण','Generating…'=>'सृजन हो रहा है…','Generation failed.'=>'सृजन असफल रहा।','Getting started'=>'शुरुआत करना ','Global AI preset'=>'वैश्विक AI पूर्वसेट','Global default (%s)'=>'वैश्विक डिफ़ॉल्ट (%s)','Glossary'=>'शब्दावली','Glossary entry added.'=>'शब्दावली प्रविष्टि जोड़ी गई।','Glossary entry removed.'=>'शब्दावली प्रविष्टि हटा दी गई।','Glossary Tab'=>'शब्दावली टैब ','Google (Gemini)'=>'गूगल (जेमिनी)','Google AI Studio'=>'गूगल AI स्टूडियो','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'H2-से-H1 मोड सक्षम — शीर्षक को H1 समकक्ष माना जाता है। (हेडिंग टैग रेंडर किए गए पृष्ठ से नहीं पहचाने गए; अपने थीम को सही ढंग से शीर्षक आउटपुट करने की पुष्टि करें।)','Heading structure rules'=>'शीर्षक संरचना नियम','Headings'=>'शीर्षक','Hide'=>'छुपाएँ','High-Performance Order Storage (HPOS)'=>'उच्च प्रदर्शन आदेश संग्रह (HPOS)','Hints'=>'संकेत','Home link text'=>'होम लिंक टेक्स्ट','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'अनुवाद में ऐसा ही दिखना चाहिए। AI को निर्देशित करने के लिए स्रोत शब्द के समान मान टाइप करें ताकि इसे शाब्दिक रूप से संरक्षित किया जाए।','How to use'=>'कैसे उपयोग करें','HPOS + CPT synced — transitional; LF post-meta filters apply to CPT copy.'=>'HPOS + CPT सिंक्ड — संक्रमणकालीन; LF पोस्ट-मेटा फ़िल्टर कॉपी पर लागू होता है।','Hreflang'=>'Hreflang','Hreflang output'=>'Hreflang आउटपुट','Hreflang settings saved.'=>'Hreflang सेटिंग्स सहेजी गईं।','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'आइकन + लेबल','Icon only'=>'केवल आइकन','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'यदि चेक किया गया है, तो प्लगइन को अनइंस्टॉल करने पर सभी भाषा असाइनमेंट, अनुवाद संबंध, मेटा विवरण, प्रति-पृष्ठ पूर्व सेटिंग्स, AI शब्दकोश, और अनुवाद स्मृति स्थायी रूप से हटा दी जाएगी। इसे वापस नहीं लिया जा सकता। जब तक आप पूरी तरह से बहुभाषी समर्थन को साइट से हटा रहे हैं, तब तक अनचेक छोड़ दें।','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'यदि आपके पास कोई सामान्य SEO प्लगइन स्थापित है, तो यह पैनल दिखाता है कि LF कैसे डुप्लिकेट आउटपुट से बचने के लिए अनुकूलित करता है। लक्ष्य टकराव से बचाव है — सहयोग नहीं। LF हमेशा बहुभाषी SEO परत प्रदान करता है (hreflang, og:locale, inLanguage schema) जो LF की भाषा राउटिंग कॉन्फ़िगरेशन के ज्ञान की आवश्यकता होती है।','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'यदि आपके पास Yoast SEO, Rank Math, All in One SEO, या SEOPress स्थापित हैं, तो Lingua Forge उन्हें पहचानता है और डुप्लिकेट आउटपुट से बचने के लिए अनुकूलित करता है। hreflang के लिए, LF पूरी तरह से नियंत्रण लेता है और प्लगइन के आउटपुट को दबाता है क्योंकि वे प्लगइन बहुभाषी राउटिंग कॉन्फ़िगरेशन के लिए सही hreflang नहीं बना सकते। Open Graph के लिए, LF केवल og:locale और og:locale:alternate जोड़ता है — बहुभाषी संकेत जो प्लगइन प्रदान नहीं कर सकता — और मूल OG सेट को प्लगइन पर छोड़ देता है। Schema.org के लिए, LF अपने आउटपुट को पूरी तरह से अक्षम कर देता है ताकि टकराव वाली JSON-LD ग्राफ से बचा जा सके।','Images'=>'छवियाँ','Improve writing'=>'लेखन में सुधार करें','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'ब्लॉक संपादक में, एक सोशल आइकन ब्लॉक जोड़ें। प्रत्येक आइकन के लिए, लिंक सेटिंग्स खोलें और नीचे दिए गए "share:" मानों में से एक को URL के रूप में दर्ज करें। फ्रंटएंड पर, LF इसे वर्तमान पृष्ठ के लिए सही शेयर URL से बदल देता है।','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'इसमें नाम, विवरण, inLanguage, url, छवि, और एक प्रस्ताव शामिल है जिसमें मूल्य, मूल्यमुद्रा, और उपलब्धता है। मूल्य और उपलब्धता स्रोत-भाषा उत्पाद से आते हैं (साझा स्टॉक मॉडल)।','Includes site name, url, and inLanguage.'=>'इसमें साइट का नाम, url, और inLanguage शामिल है।','Informative'=>'सूचनात्मक','Input tokens'=>'इनपुट टोकन','Install'=>'स्थापित करें','Install a Language'=>'एक भाषा स्थापित करें','Installed SEO plugins'=>'स्थापित SEO प्लगइन्स','Installing…'=>'इंस्टॉल हो रहा है…','instock / oos / pending from WC stock status'=>'WC स्टॉक स्थिति से इनस्टॉक / आउट ऑफ स्टॉक / लंबित','Instructions (optional)'=>'निर्देश (वैकल्पिक)','Instructions / key points'=>'निर्देश / मुख्य बिंदु','Integration API'=>'इंटीग्रेशन API ','Internal Link Fixer'=>'आंतरिक लिंक सुधारक','Introduction only'=>'केवल परिचय','Invalid API key — double-check the key entered in the AI Provider settings.'=>'अमान्य API कुंजी — AI प्रदाता सेटिंग्स में दर्ज कुंजी को दोबारा जांचें।','Invalid file reference.'=>'अमान्य फ़ाइल संदर्भ।','Invalid filename.'=>'अमान्य फ़ाइल नाम।','Invalid language code.'=>'अमान्य भाषा कोड।','Invalid language.'=>'अमान्य भाषा।','Invalid locale code.'=>'अमान्य लोकल कोड।','Invalid or primary language.'=>'अमान्य या प्राथमिक भाषा।','Invalid post ID.'=>'अमान्य पोस्ट ID।','Invalid post type.'=>'अमान्य पोस्ट प्रकार।','Invalid template part.'=>'अमान्य टेम्पलेट भाग।','Invalid template type.'=>'अमान्य टेम्पलेट प्रकार।','JavaScript-powered actions'=>'JavaScript-संचालित क्रियाएँ','Just now'=>'अभी अभी','Key points, ideas, or structure to build from…'=>'मुख्य बिंदु, विचार, या संरचना से शुरू करें…','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'कुंजी को AES-256-CBC के साथ एन्क्रिप्ट किया जाता है इससे पहले कि वह वर्डप्रेस डेटाबेस में संग्रहित हो। एन्क्रिप्शन रहस्य आपके वर्डप्रेस ऑथ सॉल्ट्स (wp-config.php) से लिया जाता है, इसलिए प्लेनटेक्स्ट कुंजी कभी भी डेटाबेस को नहीं छूती।','Landing / Short-form'=>'लैंडिंग / शॉर्ट-फॉर्म','Language'=>'भाषा','Language %s installed successfully.'=>'भाषा %s सफलतापूर्वक स्थापित।','Language (optional)'=>'भाषा (वैकल्पिक)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'इस सर्वर पर भाषा स्थापना अक्षम है (DISALLOW_FILE_MODS सेट है)।','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'इस सर्वर पर भाषा स्थापना अक्षम है। wp-config.php में DISALLOW_FILE_MODS स्थिरांक सेट है। भाषा पैक मैनुअल रूप से WP-CLI के माध्यम से स्थापित करें: wp language core install de_DE','Language label'=>'भाषा लेबल','Language Overrides'=>'भाषा ओवरराइड्स','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'भाषा ओवरराइड्स: लिंगुआ फोर्ज UI स्ट्रिंग्स के लिए कस्टम .po/.mo ओवरराइड फ़ाइलें प्रबंधित करें। इसे प्लगइन फ़ाइलों को सीधे संपादित करने के बजाय उपयोग करें — ओवरराइड अपडेट के साथ रहते हैं। ','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'भाषा पैक स्थापना विफल। भाषा पहले से ही स्थापित हो सकती है, लोकल कोड गलत हो सकता है, या आपका सर्वर फ़ाइल लेखन को ब्लॉक कर सकता है।','Language Setup'=>'भाषा सेटअप','Language Switcher'=>'भाषा स्विचर','Language switcher'=>'भाषा स्विचर ','Language uninstalled. %d post deleted.'=>'भाषा अनइंस्टॉल हो गई है। %d पोस्ट हटा दिए गए।' . "\0" . 'भाषा अनइंस्टॉल हो गई है। %d पोस्ट हटा दिए गए।','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'थीम के टेम्प्लेट भागों की भाषा-विशिष्ट प्रतियाँ। एक बार स्कैफ़ोल्ड हो जाने के बाद, टेम्प्लेट भाषा-विशिष्ट भाग का संदर्भ देने के लिए अपडेट किए जाते हैं।','Language:'=>'भाषा:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'राउटर को वर्तमान में ज्ञात भाषाएँ (स्थापित वर्डप्रेस लोकल पैक और मुख्य भाषा से प्राप्त)। अधिक भाषाओं के लिए नीचे दिए गए अनुभाग में अतिरिक्त भाषा पैक स्थापित करें।','Last 30 days'=>'पिछले 30 दिन','Last 7 days'=>'पिछले 7 दिन','Last generated: %s'=>'अंतिम जेनरेट: %s','Last rule-based SEO score. Run analysis in Settings → SEO → Analysis to update.'=>'अंतिम नियम-आधारित SEO स्कोर। अपडेट करने के लिए सेटिंग्स → SEO → विश्लेषण में विश्लेषण चलाएँ।','Last run: %s ago'=>'अंतिम रन: %s पहले','Lead paragraph (≤60 w)'=>'प्रमुख पैराग्राफ (≤60 शब्द)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'उस मॉडल फ़ील्ड को खाली छोड़ें ताकि उस स्तर के लिए अंतर्निहित डिफ़ॉल्ट का उपयोग किया जा सके। प्लेसहोल्डर टेक्स्ट दिखाता है कि कौन सा मॉडल उपयोग किया जाएगा। ','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'ब्रांड नाम और भाषा-अज्ञेय शब्दावली के लिए खाली छोड़ें जिन्हें अनुवाद से कोई फर्क नहीं पड़ता।','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'इस प्रविष्टि को सभी लक्षित भाषाओं पर लागू करने के लिए खाली छोड़ें — ब्रांड नाम, संक्षेपण, और ऐसे शब्द जो हर अनुवाद में शाब्दिक रूप से संरक्षित रहना चाहिए।','Leave blank to keep the existing key. Enter a new value to replace it.'=>'खाली छोड़ें ताकि मौजूदा कुंजी बनी रहे। इसे बदलने के लिए एक नई मान दर्ज करें।','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'डिफ़ॉल्ट का उपयोग करने के लिए खाली छोड़ें। सहेजने पर एक सहेजी गई ओवरराइड को हटाने से डिफ़ॉल्ट पुनः स्थापित हो जाता है।','Legacy lf-social-share mu-plugin'=>'Legacy lf-social-share mu-plugin','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'Legacy lf-social-share mu-plugin का पता चला। LF मूल OG सेट को mu-plugin को सौंप रहा है और केवल og:locale + og:locale:alternate आउटपुट कर रहा है। आप mu-plugin को निष्क्रिय कर सकते हैं — LF का बिल्ट-इन सोशल शेयर (SEO → सोशल शेयर टैब) और Open Graph समान कार्यक्षमता को कवर करते हैं।','Legacy post-based (CPT)'=>'विरासत पोस्ट-आधारित (CPT)','Legal / Compliance'=>'कानूनी / अनुपालन','Legal / Compliance instructions'=>'कानूनी / अनुपालन निर्देश','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF हमेशा og:locale और og:locale:alternate जोड़ता है — बहुभाषी OG संकेत जो कोई भी सामान्य SEO प्लगइन सही ढंग से नहीं बना सकता। मूल OG सेट (og:title, og:description, og:image) के लिए, LF इसे तभी आउटपुट करता है जब कोई अन्य प्लगइन मौजूद न हो। जब कोई SEO प्लगइन स्थापित हो, तो LF मूल सेट को छोड़ देता है ताकि डुप्लिकेट टैग से बचा जा सके — यह इसलिए नहीं कि प्लगइन "बेहतर" है, बल्कि क्योंकि डुप्लिकेट से कोई मूल्य नहीं बनता।','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF अपने स्वयं का साइटमैप xhtml:link विकल्पों के साथ सभी अनुवाद समूहों के लिए जेनरेट करता है। जब कोई SEO प्लगइन स्थापित हो, तो यह एक अलग साइटमैप जेनरेट करता है — दोनों स्वतंत्र रूप से सह-अस्तित्व में रहते हैं। दोनों को Google Search Console में सबमिट करें: सामग्री खोज के लिए SEO प्लगइन साइटमैप, भाषा संबंध संकेतों के लिए LF साइटमैप।','LF is outputting hreflang tags and has removed the WordPress core canonical tag on multilingual pages.'=>'LF ह्रफलैंग टैग आउटपुट कर रहा है और बहुभाषी पृष्ठों पर WordPress कोर canonical टैग हटा दिया है।','LF is suppressing hreflang output from: %s'=>'LF ह्रफलैंग आउटपुट को दबा रहा है: %s','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LF हर कॉन्फ़िगर की गई भाषा के लिए सटीक hreflang आउटपुट करता है, जिसमें x-default भी शामिल है। सामान्य SEO प्लगइन्स को आपके LF रूटिंग कॉन्फ़िगरेशन तक पहुंच नहीं है और वे गलत URL मान्यताओं के आधार पर hreflang बनाएंगे। LF उनके आउटपुट को फ़िल्टर के माध्यम से दबाता है ताकि टकराव से बचा जा सके।','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LF बहुभाषी JSON-LD के साथ inLanguage एनोटेशन के साथ आउटपुट करता है जो इसकी भाषा रूटिंग कॉन्फ़िगरेशन से जुड़ा होता है। जब कोई SEO प्लगइन इंस्टॉल किया जाता है, तो LF अपनी स्कीमा को पूरी तरह से अक्षम कर देता है: डुप्लिकेट JSON-LD ग्राफ़ मान्यकरण त्रुटियों का कारण बनते हैं और मौजूदा ग्राफ़ को पूरक करने का कोई साफ़ तरीका नहीं है।','LF provides'=>'LF प्रदान करता है','LF removes the WordPress core canonical tag on multilingual pages because the router\'s language-prefixed rewrite rules and the hreflang x-default are the correct canonical signals for a multilingual site. This prevents a double-canonical if a SEO plugin also outputs one. LF does not add its own canonical — the language routing already makes each URL canonical.'=>'LF मल्टीभाषी पृष्ठों पर WordPress कोर canonical टैग को हटा देता है क्योंकि राउटर की भाषा-प्रिफिक्स्ड रीव्राइट नियम और hreflang x-default सही canonical संकेत हैं। यह एक डबल-कैनोनिकल को रोकता है यदि कोई SEO प्लगइन भी एक आउटपुट करता है। LF अपनी खुद की canonical नहीं जोड़ता — भाषा रूटिंग पहले से ही प्रत्येक URL को canonical बनाती है।','LF-owned entries currently registered in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts. Copy these when filing a bug report.'=>'LF-स्वामित्व वाले प्रविष्टियाँ वर्तमान में $wp_rewrite->extra_rules_top में पंजीकृत हैं। 404 या रूटिंग संघर्ष का निदान करने में उपयोगी। बग रिपोर्ट दर्ज करते समय इन्हें कॉपी करें।','Light'=>'हल्का','Light (default — fast and cost-effective)'=>'हल्का (डिफ़ॉल्ट — तेज़ और लागत-कुशल)','Light (fast and cost-effective — Haiku / Flash)'=>'प्रकाश (तेज और लागत-कुशल — Haiku / Flash)','Light model'=>'लाइट मॉडल','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'लाइट: मेटा विवरण और अंश निर्माण के लिए उपयोग किया जाता है — तेज, कम लागत। ','Limit results to pages in the given Lingua Forge language code.'=>'दी गई लिंगुआ फोर्ज भाषा कोड में पृष्ठों के परिणाम सीमित करें।','Limits'=>'सीमाएँ','Lingua Forge'=>'लिंगुआ फोर्ज','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'लिंगुआ फोर्ज आपके वर्डप्रेस साइट में बहुभाषी मार्गनिर्देशन, AI-संचालित अनुवाद, hreflang SEO टैग, और एक भाषा स्विचर जोड़ता है। ','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge उत्पाद पृष्ठों पर WooCommerce-विशिष्ट Open Graph गुण जोड़ता है ताकि Facebook, Pinterest, और समान प्लेटफ़ॉर्म पर उत्पाद URL साझा करने पर सही उत्पाद प्रकार, कीमत, और उपलब्धता दिखाई दे।','Lingua Forge AI Tools'=>'लिंगुआ फोर्ज एआई टूल्स','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge WordPress Core सोशल आइकन ब्लॉक को डायनेमिक शेयर URL के साथ बढ़ाता है। किसी भी आइकन के लिंक को "share:" मान पर सेट करें और LF इसे रेंडर समय पर सही शेयर URL या जावास्क्रिप्ट क्रिया में पुनः लिख देता है — कोई कस्टम कोड या थर्ड-पार्टी प्लगइन आवश्यक नहीं।','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge /lf-sitemap.xml पर एक समर्पित XML साइटमैप बनाता है जो आपकी सभी अनुवादित सामग्री के लिए भाषा विकल्प लिंक जोड़ता है। यह साइटमैप WordPress कोर साइटमैप और किसी भी SEO प्लगइन साइटमैप का पूरक है — इसे प्रतिस्थापित नहीं करता।','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge एक पूर्ण बहुभाषी SEO समाधान है। कोई अतिरिक्त SEO प्लगइन आवश्यक नहीं है।','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge एक पूर्ण बहुभाषी SEO समाधान है। कोई अतिरिक्त SEO प्लगइन या साइटमैप प्लगइन आवश्यक नहीं है।','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'लिंगुआ फोर्ज हर कॉन्फ़िगर की गई भाषा के लिए हर पृष्ठ पर <link rel="alternate" hreflang> टैग्स आउटपुट करता है, जिसमें स्रोत भाषा की ओर इशारा करने वाला x-default भी शामिल है। यह Google और अन्य खोज इंजनों के लिए प्राथमिक बहुभाषी SEO संकेत है — कोई अतिरिक्त SEO प्लगइन आवश्यक नहीं है।','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge Open Graph और Twitter Card मेटा टैग्स आउटपुट करता है ताकि साझा किए गए URL सोशल प्लेटफ़ॉर्म पर सही भाषा, शीर्षक, विवरण, और छवि प्रदर्शित करें।','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge Schema.org JSON-LD संरचित डेटा आउटपुट करता है ताकि खोज इंजन आपकी सामग्री के प्रकार, भाषा, और मेटाडेटा को समझ सकें। यह बहुभाषी सामग्री के लिए inLanguage एनोटेशन संचार का प्राथमिक तरीका है, Google और अन्य क्रॉलर के लिए।','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge डिफ़ॉल्ट रूप से दो Gutenberg विशेषताओं को प्रतिबंधित करता है ताकि भाषाओं में संपादकीय व्यवहार सुसंगत रहे। जब आप पूर्ण Gutenberg / FSE क्षमताओं की आवश्यकता हो, तो यहाँ ऑप्ट इन करें।','Lingua Forge scopes secondary WP_Query instances (sidebar widgets, template blocks, plugin lookups) to the active language by injecting a _lf_lang meta constraint. Post types listed here are excluded from that constraint — their queries are always unfiltered.'=>'Lingua Forge सक्रिय भाषा के लिए द्वितीयक WP_Query उदाहरणों (साइडबार विजेट, टेम्प्लेट ब्लॉक, प्लगइन खोज) को स्कोप करता है _lf_lang मेटा प्रतिबंध के साथ। यहाँ सूचीबद्ध पोस्ट प्रकार इस प्रतिबंध से बाहर हैं — उनके क्वेरी हमेशा अनफ़िल्टर्ड होते हैं।','Lingua Forge Settings'=>'लिंगुआ फोर्ज सेटिंग्स ','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'लिंगुआ फोर्ज दो स्वतंत्र कैशिंग परतें उपयोग करता है ताकि दोहराए गए AI API कॉल से बचा जा सके। प्रत्येक की जांच और प्रबंधन के लिए नीचे टैब का उपयोग करें। ','Lingua Forge uses two model tiers per provider:'=>'लिंगुआ फोर्ज प्रत्येक प्रदाता के लिए दो मॉडल स्तरों का उपयोग करता है: ','Lingua Forge version'=>'Lingua Forge संस्करण','Lingua Forge — Quick Translate'=>'लिंगुआ फोर्ज — त्वरित अनुवाद','Lingua Forge — Settings'=>'लिंगुआ फोर्ज — सेटिंग्स','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'Lingua Forge का इनबिल्ट सोशल शेयर और Open Graph मॉड्यूल सभी कार्यक्षमता को कवर करता है जो mu-plugin प्रदान करता है, साथ ही बहुभाषी og:locale समर्थन भी। आप सुरक्षित रूप से mu-plugin को निष्क्रिय कर सकते हैं।','Link copied'=>'लिंक कॉपी किया गया','link(s)'=>'लिंक','Links'=>'लिंक','Load available languages'=>'उपलब्ध भाषाएँ लोड करें','Load content'=>'सामग्री लोड करें','Loaded from cache.'=>'कैश से लोड किया गया।','Loading…'=>'लोड हो रहा है…','Locale only'=>'केवल स्थानीय','Locked — a conflicting SEO plugin is active. See the notice above.'=>'लॉक्ड — एक विरोधी SEO प्लगइन सक्रिय है। ऊपर नोटिस देखें।','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate अपनी कस्टम अनुवादों को wp-content/languages/loco/ में संग्रहित करता है — एक स्थान जिसे WP कोर अपडेट, प्लगइन पुनःइंस्टॉल, या यदि Loco Translate स्वयं हटा दिया जाए तो चुपचाप मिटाया जा सकता है। यहाँ फ़ाइलें कॉपी करने से वे Lingua Forge i18n-overrides निर्देशिका में चली जाती हैं, जो इन सभी घटनाओं के दौरान बनी रहती है और हर अनुरोध पर स्वचालित रूप से लोड हो जाती है।','Loco Translate — Copy to Safe Storage'=>'Loco Translate — सुरक्षित संग्रह में कॉपी करें','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'AI सुविधाओं को ट्रिगर करने के लिए अनुमति प्राप्त सबसे कम WordPress क्षमता। इसे मजबूत करने से योगदानकर्ताओं या परीक्षण खातों को भुगतान किए गए AI कॉल चलाने से रोका जा सकता है। प्रत्येक सुविधा के लिए override करें linguaforge_required_capability फ़िल्टर के माध्यम से।','Maintenance'=>'रखरखाव','Maintenance Tab'=>'रखरखाव टैब ','Make casual'=>'आधिकारिक बनाएं','Make concise'=>'संक्षिप्त बनाएं','Make formal'=>'औपचारिक बनाएं','Manage your account, review usage, or top up credits:'=>'अपना खाता प्रबंधित करें, उपयोग की समीक्षा करें, या क्रेडिट टॉप अप करें:','Mark citations needed'=>'उद्धरण आवश्यक चिह्नित करें','Max context characters'=>'अधिकतम संदर्भ वर्ण','Max hints characters'=>'संकेतों के अधिकतम वर्ण','Max input characters'=>'अधिकतम इनपुट वर्ण','Max output tokens'=>'अधिकतम आउटपुट टोकन','Maximum characters accepted from the input field. Default: 8 000.'=>'इनपुट फ़ील्ड से स्वीकार किए गए अधिकतम वर्ण। डिफ़ॉल्ट: 8,000।','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'जब संकेत प्रदान नहीं किए जाते हैं तो AI को पास किया गया मौजूदा पोस्ट सामग्री का अधिकतम वर्ण। डिफ़ॉल्ट: 6,000।','Maximum characters read from the Hints field. Default: 2 000.'=>'संकेत फ़ील्ड से पढ़े गए अधिकतम वर्ण। डिफ़ॉल्ट: 2,000।','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'पोस्ट सामग्री की अधिकतम संख्या जो AI को भेजी जाती है। 0 का अर्थ है कोई सीमा नहीं — पूरी सामग्री हमेशा भेजी जाती है (सिफारिश की गई)। यदि आपका प्रदाता टाइट संदर्भ विंडो रखता है तो ही गैर-शून्य मान सेट करें। जब सामग्री को ट्रिम किया जाता है तो PHP त्रुटि लॉग में चेतावनी लिखी जाती है।','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'एकल अनुवाद प्रतिक्रिया में AI द्वारा उत्पन्न अधिकतम टोकन की संख्या। यदि अनुवाद चुपचाप समाप्त हो रहा है, तो इस मान को बढ़ाएँ। डिफ़ॉल्ट: 16,000।','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'प्रति पीढ़ी रन AI द्वारा उत्पादित अधिकतम टोकन। यदि पूर्ण लेख कट रहे हैं तो इसे बढ़ाएँ। डिफ़ॉल्ट: 8,192।','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'प्रति त्वरित अनुवाद AI द्वारा उत्पादित अधिकतम टोकन। डिफ़ॉल्ट: 2,000।','Meta Description'=>'मेटा विवरण','Meta description'=>'मेटा विवरण','Meta Description, Excerpt Generator'=>'मेटा विवरण, सारांश जनरेटर','Meta Description, Excerpt Generator, quick translate'=>'मेटा विवरण, अंश निर्माता, त्वरित अनुवाद','Metric'=>'मेट्रिक','Minimum role'=>'न्यूनतम भूमिका','Missing'=>'मिसिंग','Missing pattern name or language.'=>'पैटर्न नाम या भाषा गायब है।','Mode'=>'मोड','Model'=>'मॉडल','Model ID'=>'मॉडल ID','Model tier'=>'मॉडल स्तर','Models'=>'मॉडल','Models Tab (General)'=>'मॉडल टैब (सामान्य) ','Modified'=>'संशोधित','Most recent cached block'=>'सबसे हाल की कैश की गई ब्लॉक ','Most recent cached response'=>'सबसे हाल की कैश की गई प्रतिक्रिया ','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'बहुभाषी रूटिंग, पूर्ण बहुभाषी SEO (hreflang, Open Graph, Schema.org, साइटमैप), और WordPress के लिए AI सामग्री उपकरण। भाषा पहचान, URL रूटिंग, अनुवाद, सामग्री निर्माण, और एक पूर्ण SEO परत — कोई साथी प्लगइन आवश्यक नहीं।','Multilingual SEO'=>'बहुभाषी SEO','Multilingual SEO overview'=>'बहुभाषी SEO अवलोकन','My Account'=>'मेरा खाता','Name'=>'नाम','Name displayed in this language. Leave empty to use the source name.'=>'इस भाषा में प्रदर्शित नाम। स्रोत नाम का उपयोग करने के लिए खाली छोड़ दें।','Navigation'=>'नेविगेशन','Navigation has no content to translate.'=>'नेविगेशन में अनुवाद करने के लिए कोई सामग्री नहीं है।','Navigation not found.'=>'नेविगेशन नहीं मिला।','Navigation posts are translated via the Router tab, not this button.'=>'नेविगेशन पोस्ट राउटर टैब के माध्यम से अनुवादित होते हैं, इस बटन के माध्यम से नहीं।','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'नेविगेशन अनुवाद के लिए एक सक्रिय AI प्रदाता आवश्यक है। API कुंजी को API Keys टैब में कॉन्फ़िगर करें।','Navigations'=>'नेविगेशन','Network error — could not reach the provider: %s'=>'नेटवर्क त्रुटि — प्रदाता से संपर्क नहीं कर सका: %s','Network error — could not reach the WordPress AJAX endpoint.'=>'नेटवर्क त्रुटि — वर्डप्रेस AJAX एंडपॉइंट तक नहीं पहुंच सका।','Network error.'=>'नेटवर्क त्रुटि।','Never run'=>'कभी नहीं चलाएँ','No %s version found in this translation group.'=>'इस अनुवाद समूह में कोई %s संस्करण नहीं मिला।','No action needed. Google deprecated its sitemap ping endpoint in January 2024 and now discovers sitemaps exclusively via the robots.txt Sitemap: directive — which LF has already configured. Google will pick it up on its next crawl.'=>'कोई कार्रवाई आवश्यक नहीं। Google ने जनवरी 2024 में अपनी साइटमैप पिंग एंडपॉइंट को बंद कर दिया है और अब केवल robots.txt Sitemap: निर्देश के माध्यम से साइटमैप खोजता है — जिसे LF ने पहले ही कॉन्फ़िगर कर दिया है। Google इसे अपने अगले क्रॉल पर उठाएगा।','No active plugins detected.'=>'कोई सक्रिय प्लगइन्स नहीं पाए गए।','No AI provider configured.'=>'कोई एआई प्रदाता कॉन्फ़िगर नहीं किया गया।','No AI provider configured. Add an API key in Settings → API Keys.'=>'कोई AI प्रदाता कॉन्फ़िगर नहीं किया गया। सेटिंग्स → API Keys में एक API कुंजी जोड़ें।','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'चयनित विंडो (%s) में कोई एआई उपयोग रिकॉर्ड नहीं हुआ है। ऊपर एक व्यापक सीमा चुनें।','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'अभी तक कोई एआई उपयोग रिकॉर्ड नहीं हुआ है। एक संपादक जब अनुवाद करता है, मेटा विवरण उत्पन्न करता है, या किसी अन्य एआई सुविधा का उपयोग करता है, तो कुल यहां दिखाई देंगे।','No API key configured for this provider.'=>'इस प्रदाता के लिए कोई API कुंजी कॉन्फ़िगर नहीं की गई है।','No API key configured — enter your key in the AI Provider settings.'=>'कोई API कुंजी कॉन्फ़िगर नहीं — अपनी कुंजी AI प्रदाता सेटिंग्स में दर्ज करें।','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'कोई इन-बिल्ट निर्देश नहीं — प्रत्येक AI सुविधा अपने ट्यून किए गए डिफ़ॉल्ट का उपयोग करती है। नीचे कस्टम प्रॉम्प्ट निर्देश फ़ील्ड भरें ताकि आप अपनी साइट-व्यापी नियम जोड़ सकें।','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'कोई विरोधी SEO प्लगइन्स का पता नहीं चला। Lingua Forge सभी SEO आउटपुट को स्वतंत्र रूप से संभाल रहा है।','No credits remaining — top up your OpenAI account at platform.openai.com/account/billing.'=>'कोई क्रेडिट शेष नहीं — अपने OpenAI खाते को platform.openai.com/account/billing पर टॉप अप करें।','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'अभी तक कोई कस्टम Loco Translate फ़ाइलें नहीं मिली हैं। जब आप Loco Translate में अनुवाद सहेजते हैं तो ये यहाँ दिखाई देती हैं।','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'कोई बाहरी OG प्लगइन का पता नहीं चला। LF पूरा OG + Twitter Card सेट आउटपुट कर रहा है।','No file was selected.'=>'कोई फ़ाइल चयनित नहीं की गई।','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'वर्तमान फ़िल्टर से मेल खाने वाली कोई भी शब्दावली प्रविष्टि नहीं है। सभी प्रविष्टियों को देखने के लिए फ़िल्टर साफ़ करें, या नीचे एक नई प्रविष्टि जोड़ें।','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'अभी तक कोई शब्दावली प्रविष्टि नहीं है। अनुवाद में शब्दावली लागू करने के लिए नीचे एक जोड़ें।','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'कोई H1 नहीं मिला। आमतौर पर पोस्ट का शीर्षक H1 होता है — सुनिश्चित करें कि आपका थीम इसे आउटपुट कर रहा है।','No images found in content.'=>'सामग्री में कोई छवियां नहीं मिलीं।','No internal links found to update.'=>'अपडेट करने के लिए कोई आंतरिक लिंक नहीं मिले।','No key'=>'कोई कुंजी नहीं','No language-specific template parts found to map.'=>'मॉप करने के लिए कोई भाषा-विशिष्ट टेम्पलेट भाग नहीं मिला।','No LF meta description set — using excerpt/content.'=>'कोई LF मेटा विवरण सेट नहीं — सारांश/सामग्री का उपयोग कर रहा है।','No LF rewrite rules found. Flush permalinks if this is unexpected.'=>'कोई LF पुनर्लेखन नियम नहीं मिले। यदि यह अप्रत्याशित है तो स्थायी लिंक को फ्लश करें।','No links found.'=>'कोई लिंक नहीं मिला।','No links found. Internal links improve crawlability and user navigation.'=>'कोई लिंक नहीं मिला। आंतरिक लिंक क्रॉलबिलिटी और उपयोगकर्ता नेविगेशन में सुधार करते हैं।','No meta description found. Generate one via the AI meta description feature.'=>'कोई मेटा विवरण नहीं मिला। AI मेटा विवरण सुविधा का उपयोग करके एक बनाएं।','No navigation references needed updating.'=>'कोई नेविगेशन संदर्भ अपडेट करने की आवश्यकता नहीं है।','No override files uploaded yet.'=>'अभी तक कोई ओवरराइड फ़ाइलें अपलोड नहीं की गई हैं।','No PHP limit'=>'कोई PHP सीमा नहीं','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'कोई भौतिक robots.txt फ़ाइल नहीं मिली। WordPress इसे वर्चुअली जेनरेट कर रहा है और LF का Sitemap निर्देश स्वचालित रूप से शामिल है।','No published posts found for the selected filters.'=>'चयनित फ़िल्टर के लिए कोई प्रकाशित पोस्ट नहीं मिली।','No response from AI provider. Check your API key and try again.'=>'AI प्रदाता से कोई प्रतिक्रिया नहीं। अपनी API कुंजी जांचें और पुनः प्रयास करें।','No response from provider — check the error log for details.'=>'प्रदाता से प्रतिक्रिया नहीं मिली — विवरण के लिए त्रुटि लॉग जांचें।','No secondary languages configured.'=>'कोई द्वितीयक भाषाएँ कॉन्फ़िगर नहीं की गई हैं।','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'कोई द्वितीयक भाषाएँ कॉन्फ़िगर नहीं हैं। टेम्प्लेट स्कैफ़ोल्डिंग सक्षम करने के लिए ऊपर एक भाषा पैक स्थापित करें।','No source content found to translate.'=>'अनुवाद करने के लिए स्रोत सामग्री नहीं मिली।','No source page linked yet.'=>'अभी तक कोई स्रोत पृष्ठ लिंक नहीं है।','No template part references needed updating.'=>'कोई टेम्पलेट भाग संदर्भ अपडेट करने की आवश्यकता नहीं है।','No third-party SEO plugins detected. Lingua Forge handles all multilingual SEO output.'=>'कोई तीसरे पक्ष के SEO प्लगइन्स का पता नहीं चला। Lingua Forge सभी बहुभाषी SEO आउटपुट का प्रबंधन करता है।','No title set.'=>'कोई शीर्षक सेट नहीं।','No translated content found. The sitemap will populate once posts have been translated.'=>'कोई अनुवादित सामग्री नहीं मिली। पोस्ट का अनुवाद होने के बाद साइटमैप भर जाएगा।','No translation found — analyzed the source language version.'=>'कोई अनुवाद नहीं मिला — स्रोत भाषा संस्करण का विश्लेषण किया गया।','No {lang} translation registered (TRID missing)'=>'कोई {lang} अनुवाद पंजीकृत नहीं है (TRID गायब)','No — WooCommerce integration class not loaded'=>'कोई — WooCommerce एकीकरण क्लास लोड नहीं हुआ','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'अभी तक जेनरेट नहीं हुआ। साइटमैप पहली बार साइटमैप URL पर जाने पर बनता है और 24 घंटे के लिए कैश हो जाता है।','Notes'=>'टिप्पणियाँ','Nothing — all types disabled'=>'कुछ नहीं — सभी प्रकार अक्षम हैं।','Notice message'=>'सूचना संदेश','Notice settings'=>'सूचना सेटिंग्स','Notify search engines'=>'खोज इंजनों को सूचित करें','Numeric permalink structure is not supported.'=>'संख्यात्मक permalink संरचना समर्थित नहीं है।','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'OG/Twitter Card टैग्स: LF के Open Graph मॉड्यूल द्वारा संभाला गया (SEO → Open Graph & Twitter Cards)','Oldest cached block'=>'सबसे पुराना कैश की गई ब्लॉक ','Oldest cached response'=>'सबसे पुराना कैश की गई प्रतिक्रिया ','Only .mo files are accepted.'=>'केवल .mo फ़ाइलें स्वीकार की जाती हैं।','Open Graph'=>'Open Graph','Open Graph &amp; Twitter Cards'=>'ओपन ग्राफ़ और ट्विटर कार्ड्स','Open Graph output'=>'Open Graph आउटपुट','Open Graph settings saved.'=>'Open Graph सेटिंग्स सहेजी गईं।','Open Search Console →'=>'Open Search Console →','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'ब्राउज़र के नेटिव Web Share शीट (iOS, Android, कुछ डेस्कटॉप) खोलें। यदि समर्थित नहीं है तो क्लिपबोर्ड कॉपी परFallback।','OpenAI (GPT)'=>'ओपनएआई (जीपीटी)','OpenAI Platform'=>'OpenAI प्लेटफ़ॉर्म','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'संपादकों के लिए वैकल्पिक संदर्भ (जैसे "ASIC = एप्लिकेशन-विशिष्ट इंटीग्रेटेड सर्किट; तकनीकी संदर्भ में अंग्रेजी में संरक्षित करें")।','Optional. Bing already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'वैकल्पिक। Bing पहले ही robots.txt से Sitemap: निर्देश पढ़ता है — यह केवल अगली निर्धारित जांच का इंतजार किए बिना तुरंत पुनः क्रॉल को ट्रिगर करता है।','Optional. Yandex already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'वैकल्पिक। Yandex पहले ही robots.txt से Sitemap: निर्देश पढ़ता है — यह केवल अगली निर्धारित जांच का इंतजार किए बिना तुरंत पुनः क्रॉल को ट्रिगर करता है।','Order storage'=>'आदेश संग्रह','Orders in wp_posts — ensure shop_order is excluded from LF routing.'=>'wp_posts में आदेश — सुनिश्चित करें कि shop_order को LF राउटिंग से बाहर रखा गया है।','Output'=>'आउटपुट','Output Article or WebPage schema on singular posts and pages'=>'सिंगल पोस्ट और पृष्ठों पर आर्टिकल या वेबपेज स्कीमा आउटपुट करें','Output hreflang tags in wp_head'=>'wp_head में hreflang टैग्स आउटपुट करें','Output mode'=>'आउटपुट मोड','Output Open Graph tags in wp_head'=>'wp_head में Open Graph टैग्स आउटपुट करें','Output Product schema on WooCommerce product pages'=>'WooCommerce उत्पाद पृष्ठों पर उत्पाद स्कीमा आउटपुट करें','Output Schema.org JSON-LD in wp_head'=>'आउटपुट Schema.org JSON-LD wp_head में','Output tokens'=>'आउटपुट टोकन','Output WebSite schema on the front page and blog index'=>'मुख्य पृष्ठ और ब्लॉग सूचकांक पर WebSite schema का आउटपुट','Overall SEO score'=>'कुल SEO स्कोर','overridden'=>'ओवरराइड किया गया','Override file deleted.'=>'ओवरराइड फ़ाइल हटा दी गई।','Override file uploaded successfully.'=>'ओवरराइड फ़ाइल सफलतापूर्वक अपलोड की गई।','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'इस पृष्ठ पर अनुवाद और सामग्री निर्माण के लिए एआई पूर्वनिर्धारित को ओवरराइड करता है। सभी अन्य सुविधाएँ हमेशा वैश्विक पूर्वनिर्धारित का उपयोग करती हैं।','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'इस पृष्ठ पर अनुवाद और सामग्री निर्माण के लिए एआई पूर्वनिर्धारित को ओवरराइड करता है। साइट-व्यापी कस्टम प्रॉम्प्ट निर्देश (सेटिंग्स → व्यवहार) हर अनुरोध में जोड़े जाते हैं, इस चयन के बावजूद।','Overview'=>'समीक्षा ','Page'=>'पृष्ठ','Part'=>'भाग','Paste a footnote, sentence, or any snippet here…'=>'यहां फुटनोट, वाक्य, या कोई भी अंश चिपकाएं…','Paste text, or select text in the editor first…'=>'पाठ चिपकाएँ, या पहले संपादक में पाठ चुनें…','Paste text, or select text on the page first…'=>'पाठ चिपकाएँ, या पहले पृष्ठ पर पाठ चुनें…','Paste your API key…'=>'अपनी एपीआई कुंजी चिपकाएँ…','Path prefix (/de/)'=>'पथ उपसर्ग (/de/)','Path prefix — example.com/de/'=>'पथ उपसर्ग — example.com/de/','Path routing requires a post-name based permalink structure. Change it in'=>'पथ राउटिंग पोस्ट-नाम आधारित permalink संरचना की आवश्यकता है। इसे में बदलें','Pattern'=>'पैटर्न','Pattern has no content to translate.'=>'पैटर्न में अनुवाद करने के लिए कोई सामग्री नहीं है।','Pattern not found.'=>'पैटर्न नहीं मिला।','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'पैटर्न का अनुवाद किया गया और सहेजा गया। सामग्री को अपने सीपीटी पोस्ट में ब्लॉक संपादक पैटर्न इंसर्टर के माध्यम से कॉपी करें या इसे एक पुन: प्रयोज्य ब्लॉक के रूप में शुरूआत के रूप में उपयोग करें।','Pattern translation failed.'=>'पैटर्न अनुवाद असफल रहा।','Payment required — your account has no remaining credits.'=>'भुगतान आवश्यक — आपके खाते में शेष क्रेडिट नहीं हैं।','Per-Post Analysis'=>'प्रति-प्रस्ताव विश्लेषण','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Entries are invalidated automatically when the content or AI provider/model changes.'=>'AI-निर्मित अनुवाद, मेटा विवरण, अंश, और सामग्री के लिए प्रति-प्रस्ताव कैश। जब सामग्री या AI प्रदाता/मॉडल बदलता है तो प्रविष्टियों को स्वचालित रूप से अमान्य कर दिया जाता है।','Permalink rules flushed successfully.'=>'Permalink नियम सफलतापूर्वक फ्लश किए गए।','Permalink Structure'=>'Permalink संरचना','Permalink structure is compatible with Lingua Forge path routing.'=>'Permalink संरचना Lingua Forge पथ राउटिंग के साथ संगत है।','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'स्थायी रूप से इस भाषा से संबंधित सभी टेम्पलेट, टेम्पलेट भाग, पैटर्न, नेविगेशन मेनू, पोस्ट, पृष्ठ, कस्टम पोस्ट प्रकार, उत्पाद, और उत्पाद भिन्नताएँ हटा देता है। साथ ही वर्डप्रेस लोकल पैक फ़ाइलें भी हटा देता है ताकि यह भाषा अब राउटर में न दिखाई दे। यह क्रिया पूर्ववत नहीं की जा सकती।','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'क्या आप स्थायी रूप से %s को अनइंस्टॉल करना चाहते हैं? इससे इस भाषा के सभी अनुवादित सामग्री हटा दी जाएगी और इसे पूर्ववत नहीं किया जा सकता।','Permission denied.'=>'अनुमति अस्वीकृत।','Persuasive'=>'प्रेरक','PHP constant'=>'PHP स्थिरांक','PHP max_execution_time'=>'PHP अधिकतम निष्पादन समय','PHP memory_limit'=>'PHP मेमोरी सीमा','PHP version'=>'PHP संस्करण','Pin on Pinterest'=>'Pinterest पर पिन करें','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'उन शब्दों को पिन करें जिन्हें अनुवादित नहीं किया जाना चाहिए या जिन्हें विशिष्ट तरीके से हमेशा प्रस्तुत किया जाना चाहिए (जैसे ब्रांड नाम, उत्पाद नाम, संक्षेपाक्षर)। शब्दावली सीमाएँ हर AI अनुवाद अनुरोध में इंजेक्ट की जाती हैं: पोस्ट अनुवाद, मेटा विवरण, अंश, और FSE टेम्प्लेट अनुवाद। ','Ping Bing'=>'Bing को पिंग करें','Ping Yandex'=>'Yandex को पिंग करें','Plain language'=>'सामान्य भाषा','Plain permalinks are not supported.'=>'साधारण permalink समर्थित नहीं हैं।','Please enter some instructions first…'=>'कृपया पहले कुछ निर्देश दर्ज करें…','Please enter some text first…'=>'कृपया पहले कुछ टेक्स्ट दर्ज करें…','Plugin'=>'प्लगइन','Post'=>'पोस्ट','Post not found or not published.'=>'पोस्ट नहीं मिली या प्रकाशित नहीं है।','Post not found.'=>'पोस्ट नहीं मिली।','Post on X / Twitter'=>'X / Twitter पर पोस्ट करें','Post type'=>'प्रकार पोस्ट','Post type slugs separated by commas or newlines. Changes take effect immediately on save — no permalink flush required.'=>'पोस्ट प्रकार स्लग को कॉमा या नई लाइनों से अलग किया गया है। परिवर्तन तुरंत प्रभावी होते हैं जब आप सहेजते हैं — कोई permalink फ्लश आवश्यक नहीं।','Post Types'=>'पोस्ट टाइप्स','Posts without _lf_lang are invisible to every Lingua Forge language filter. This can happen when content is imported or created before the plugin was activated.'=>'_lf_lang के बिना पोस्ट हर Lingua Forge भाषा फ़िल्टर के लिए अदृश्य हैं। यह तब हो सकता है जब सामग्री आयात की जाती है या प्लगइन सक्रिय होने से पहले बनाई जाती है।','Prefilled from excerpt. Edit to override.'=>'अग्रिम से भरा हुआ है। ओवरराइड करने के लिए संपादित करें।','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'मूल भाषा उत्पाद की कीमत और उपलब्धता हमेशा दर्शाता है (साझा स्टॉक मॉडल)। टैग तभी आउटपुट होते हैं जब LF का Open Graph मॉड्यूल "पूर्ण" या "ऑटो" मोड पर सेट हो और कोई विरोधी SEO प्लगइन न हो।','Primary content language'=>'प्राथमिक सामग्री भाषा','Primary Language'=>'प्राथमिक भाषा','Primary language'=>'प्राथमिक भाषा','Primary language saved.'=>'प्राथमिक भाषा सहेजी गई।','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'प्राथमिक भाषा: वह भाषा जिसमें आपका मौजूदा सामग्री लिखा है। सभी अनुवाद इसी भाषा से बनाए जाते हैं; इसे बदलने से कोई पोस्ट स्थानांतरित या हटा नहीं दी जाती। ','Processing…'=>'प्रक्रिया में…','Product'=>'उत्पाद','Product / eCommerce'=>'उत्पाद / ईकॉमर्स','Product Open Graph'=>'उत्पाद Open Graph','Product — WooCommerce product pages'=>'उत्पाद — WooCommerce उत्पाद पृष्ठ','Profile'=>'प्रोफ़ाइल','Profiles adapt thresholds and weights to the type of content being analysed. Profile is resolved automatically; you can override it per analysis run from the profile dropdown.'=>'प्रोफाइल थ्रेशोल्ड और वज़नों को विश्लेषण की जा रही सामग्री के प्रकार के अनुसार अनुकूलित करता है। प्रोफाइल स्वचालित रूप से हल किया जाता है; आप इसे प्रोफाइल ड्रॉपडाउन से प्रत्येक विश्लेषण रन पर ओवरराइड कर सकते हैं।','Provider'=>'प्रदाता','Provider error (HTTP %1$d): %2$s'=>'प्रदाता त्रुटि (HTTP %1$d): %2$s','Provider returned no response. Check the WordPress error log for details.'=>'प्रदाता ने कोई प्रतिक्रिया नहीं दी। विवरण के लिए WordPress त्रुटि लॉग जांचें।','Provider service temporarily unavailable — try again in a moment.'=>'प्रदाता सेवा अस्थायी रूप से अनुपलब्ध — फिर से प्रयास करें।','Quality'=>'गुणवत्ता','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'गुणवत्ता (डिफ़ॉल्ट — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'गुणवत्ता (Sonnet / GPT-4o / Gemini Pro)','Quality model'=>'गुणवत्ता मॉडल','Quality: used for post translation and content generation — higher quality, higher cost.'=>'गुणवत्ता: पोस्ट अनुवाद और सामग्री निर्माण के लिए — उच्च गुणवत्ता, उच्च लागत। ','Query Filter Exclusions'=>'प्रश्न फ़िल्टर बहिष्करण','Quick Translate'=>'त्वरित अनुवाद','Quick Translation'=>'त्वरित अनुवाद','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'त्वरित अनुवाद का उपयोग स्निपेट/चंक मोड के लिए किया जाता है — टूलबार, संपादक, या ब्लॉक पॉपओवर से मांग पर छोटे अंशों का अनुवाद। यह पूर्ण-पृष्ठ अनुवाद से अलग, हल्के कॉन्फ़िगरेशन का उपयोग करता है ताकि प्रतिक्रियाएँ तेज़ और लागत-कुशल रहें।','Rate limited — too many requests sent to the provider; wait a moment and try again.'=>'दर सीमा लगी — प्रदाता को बहुत अधिक अनुरोध भेजे गए हैं; एक पल प्रतीक्षा करें और फिर से प्रयास करें।','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Gutenberg\'s canLockBlocks को पुनः सक्षम करता है। संपादकीय टेम्प्लेट के लिए उपयोगी है जो योगदानकर्ताओं को विशिष्ट ब्लॉक को स्थानांतरित या हटाने से रोकने की आवश्यकता होती है।','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'supportsTemplateMode को पुनः सक्षम करता है। यह पूर्ण-साइट-एडिटिंग वर्कफ़्लोज़ के लिए मुख्य है जहां पोस्ट-स्तर टेम्प्लेट ओवरराइड इरादतन होते हैं।','Re-generates and updates the cached result.'=>'कैश किए गए परिणाम को पुनः जेनरेट और अपडेट करता है।','Re-scan'=>'पुनः स्कैन करें','Re-scanning…'=>'पुनः स्कैन कर रहे हैं…','Re-translate'=>'पुनः अनुवाद करें','Reading time'=>'पढ़ने का समय','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'ब्राउज़र के Accept-Language हेडर के आधार पर आगंतुकों को उनकी पसंदीदा भाषा में पुनः निर्देशित करें','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'अधिक परिष्कृत करें — जैसे "इसे छोटा करें" या "औपचारिक टोन का उपयोग करें"…','Refine further:'=>'अधिक परिष्कृत करें:','Refinement'=>'सुधार','Refinement failed — please try again.'=>'सुधार असफल रहा — कृपया पुनः प्रयास करें।','Refining…'=>'सुधार रहा है…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'वर्डप्रेस रीव्राइट नियमों को पुनः जेनरेट करता है ताकि URL उपसर्ग, भाषा-विशिष्ट स्लग, और आर्काइव रीव्राइट्स सभी सिंक में हों। मुख्य भाषा बदलने या नई भाषा समर्थन जोड़ने के बाद आवश्यक।','Remove stored key'=>'संग्रहीत कुंजी हटाएँ','Repair failed.'=>'मरम्मत विफल।','Repair tags every routable post listed above with _lf_lang = %s. Posts in routing-excluded post types are not touched. Only run this after importing content or on initial activation — do not use as a bulk language-reassignment tool.'=>'ऊपर सूचीबद्ध राउटेबल पोस्ट के टैग की मरम्मत करें _lf_lang = %s के साथ। राउटिंग-बहिष्कृत पोस्ट प्रकारों में पोस्ट को नहीं छुआ जाएगा। इसे केवल सामग्री आयात करने के बाद या प्रारंभिक सक्रियण पर चलाएं — इसे एक बल्क भाषा-फिर से निर्धारित उपकरण के रूप में उपयोग न करें।','Repair — assign _lf_lang = %s to all routable posts above'=>'मरम्मत — ऊपर के सभी राउटेबल पोस्ट को _lf_lang = %s असाइन करें','Repairing…'=>'मरम्मत हो रही है…','Report an issue on GitHub'=>'GitHub पर समस्या रिपोर्ट करें ','Request failed — please try again.'=>'अनुरोध असफल रहा — कृपया पुनः प्रयास करें।','Request failed.'=>'अनुरोध असफल रहा।','Request failed. Check your connection.'=>'अनुरोध असफल। अपना कनेक्शन जांचें।','Request failed. Please try again.'=>'अनुरोध असफल। कृपया पुनः प्रयास करें।','Requests'=>'अनुरोध','requests / day'=>'दिन में अनुरोध','Reset'=>'रीसेट','Result will appear here…'=>'परिणाम यहाँ दिखाई देगा…','Retranslate'=>'पुनः अनुवाद करें','Retranslating…'=>'पुनः अनुवाद हो रहा है…','Review carefully — links and slugs not updated.'=>'सावधानीपूर्वक समीक्षा करें — लिंक और स्लग अपडेट नहीं किए गए।','Review translation before applying'=>'लागू करने से पहले अनुवाद की समीक्षा करें','Revise'=>'समीक्षा','Revision'=>'समीक्षा','Revision Type'=>'समीक्षा प्रकार','Rewrite Rules'=>'पुनर्लेखन नियम','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt को Sitemap निर्देश के साथ अपडेट किया गया।','Router'=>'राउटर','Router Tab'=>'राउटर टैब ','Run a full SEO audit across all published posts for one or all active languages. Scores are saved per post and reflected in the Language column badges in the post list.'=>'सभी प्रकाशित पोस्ट के लिए एक पूर्ण SEO ऑडिट चलाएँ, एक या सभी सक्रिय भाषाओं के लिए। स्कोर प्रत्येक पोस्ट पर सहेजे जाते हैं और पोस्ट सूची में भाषा कॉलम बैज में दर्शाए जाते हैं।','Run AI Analysis'=>'AI विश्लेषण चलाएँ','Save'=>'सहेजें','Save analysis settings'=>'विश्लेषण सेटिंग्स सहेजें','Save Debug Setting'=>'डिबग सेटिंग सहेजें','Save Hreflang Settings'=>'Hreflang सेटिंग्स सहेजें','Save Open Graph Settings'=>'Open Graph सेटिंग्स सहेजें','Save Router Settings'=>'राउटर सेटिंग्स सहेजें','Save Schema.org Settings'=>'Schema.org सेटिंग्स सहेजें','Save Settings'=>'सेटिंग्स सहेजें','Save Sitemap Settings'=>'Sitemap सेटिंग्स सहेजें','Save Social Share Settings'=>'सामाजिक शेयर सेटिंग्स सहेजें','Save the post to persist changes.'=>'परिवर्तनों को स्थायी बनाने के लिए पोस्ट सहेजें।','Save Uninstall Setting'=>'अस्थायी सेटिंग सहेजें','Save WooCommerce SEO Settings'=>'WooCommerce SEO सेटिंग्स सहेजें','Saved to the meta description field when you apply.'=>'जब आप लागू करते हैं तो मेटा विवरण क्षेत्र में सहेजा जाता है।','Scan failed: '=>'स्कैन विफल: ','Scan request failed. Please try again.'=>'स्कैन अनुरोध विफल। कृपया पुनः प्रयास करें।','Scanning posts for broken language links…'=>'भाषा लिंक टूटने के लिए पोस्ट स्कैन कर रहे हैं…','Schema output deferred.'=>'Schema आउटपुट स्थगित।','Schema.org'=>'Schema.org','Schema.org JSON-LD'=>'Schema.org JSON-LD','Schema.org output'=>'Schema.org आउटपुट','Schema.org settings saved.'=>'Schema.org सेटिंग्स सहेजी गईं।','Score'=>'स्कोर','Score computation'=>'स्कोर गणना','Score history and badges'=>'स्कोर इतिहास और बैज','Scores are a signal, not a verdict. Some content is structurally limited — very short pages, landing pages with little body text, or pages whose purpose is navigation rather than information may score lower by nature. Use this overview to spot genuine parity gaps across languages, not to chase a number.'=>'स्कोर एक संकेत है, निर्णय नहीं। कुछ सामग्री संरचनात्मक रूप से सीमित होती है — बहुत छोटी पृष्ठें, कम बॉडी टेक्स्ट वाली लैंडिंग पृष्ठें, या पृष्ठें जिनका उद्देश्य नेविगेशन है न कि जानकारी, स्वाभाविक रूप से कम स्कोर कर सकती हैं। इस अवलोकन का उपयोग भाषाओं के बीच वास्तविक समानता अंतराल को देखने के लिए करें, न कि संख्या का पीछा करने के लिए।','Search'=>'खोज','Search Console is useful for monitoring indexing and coverage errors, but is not required for discovery.'=>'सर्च कंसोल अनुक्रमण और कवरेज त्रुटियों की निगरानी के लिए उपयोगी है, लेकिन खोज के लिए आवश्यक नहीं है।','Search Results'=>'खोज परिणाम','Security check failed — file path is not permitted.'=>'सुरक्षा जांच विफल — फ़ाइल पथ अनुमति प्राप्त नहीं है।','See Settings → SEO → Compatibility for the full per-feature behaviour table.'=>'पूर्ण फीचर व्यवहार तालिका के लिए सेटिंग्स → SEO → संगतता देखें।','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'उस भाषा का चयन करें ताकि उसकी FSE टेम्प्लेट, टेम्प्लेट भाग, और नेविगेशन मेनू का प्रबंधन किया जा सके।','Select a post and run a detailed SEO audit to see per-metric results and a score for that specific item.'=>'एक पोस्ट चुनें और उस विशिष्ट आइटम के लिए प्रति-मेट्रिक परिणाम और स्कोर देखने के लिए एक विस्तृत SEO ऑडिट चलाएँ।','Select language'=>'भाषा चुनें ','Send via Telegram'=>'टेलीग्राम के माध्यम से भेजें','Send via WhatsApp'=>'WhatsApp के माध्यम से भेजें','SEO'=>'एसईओ','SEO Analysis'=>'एसईओ विश्लेषण','SEO character-count info'=>'एसईओ अक्षर गणना जानकारी','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'SEO प्लगइन(s) का पता चला: %s। LF केवल og:locale और og:locale:alternate आउटपुट कर रहा है; पता लगाने वाला प्लगइन पूर्ण OG सेट को संभालता है।','SEO Plugins'=>'SEO प्लगइन्स','SEO plugins and conflict avoidance:'=>'एसईओ प्लगइन्स और संघर्ष से बचाव:','SEO Score System'=>'एसईओ स्कोर सिस्टम','SEO Scores'=>'एसईओ स्कोर','SEO Tab'=>'एसईओ टैब','Server setup (subdomain)'=>'सर्वर सेटअप (उपडोमेन) ','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'साइट-व्यापी सभी सुविधाओं के लिए डिफ़ॉल्ट AI व्यवहार सेट करता है। व्यक्तिगत पोस्ट इसको ओवरराइड कर सकते हैं, जैसे अनुवाद और सामग्री निर्माण, Lingua Forge मेटा बॉक्स के माध्यम से।','Settings'=>'सेटिंग्स','Settings saved.'=>'सेटिंग्स सहेजी गई।','Settings → Permalinks'=>'सेटिंग्स → permalink','Share on Facebook'=>'फेसबुक पर साझा करें','Share on LinkedIn'=>'LinkedIn पर साझा करें','Share on Mastodon'=>'Mastodon पर साझा करें','Share via email (mailto:)'=>'ईमेल के माध्यम से साझा करें (mailto:)','Shared / compatibility mode'=>'साझा / अनुकूलता मोड','Shop'=>'दुकान','Short content (3 paragraphs or fewer) is never penalised for missing subheadings, regardless of profile. A concise page does not benefit from forced heading structure.'=>'संक्षिप्त सामग्री (3 पैराग्राफ या कम) को कभी भी उपशीर्षक की अनुपस्थिति के लिए दंडित नहीं किया जाता है, प्रोफाइल की परवाह किए बिना। एक संक्षिप्त पृष्ठ को जबरदस्ती शीर्षक संरचना से लाभ नहीं होता।','Show home link'=>'होम लिंक दिखाएँ','Shown when no translation exists for the visitor\'s language.'=>'जब कोई अनुवाद आगंतुक की भाषा के लिए मौजूद नहीं होता है तो दिखाया जाता है।','Single'=>'एकल','Single %s'=>'एकल %s','Single-word title (%d chars) — adding a second word improves clarity and keyword coverage.'=>'एकल शब्द शीर्षक (%d वर्ण) — दूसरा शब्द जोड़ने से स्पष्टता और कीवर्ड कवरेज में सुधार होता है।','Single: %s'=>'एकल: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'UTC दिन के लिए साइट-व्यापी AI अनुरोध सीमा (टूलबार अनुवाद और ब्लॉक संशोधन दोनों को गिनता है)। काउंटर UTC मध्यरात्रि पर रीसेट होता है। इसे अक्षम करने के लिए 0 सेट करें।','Sitemap'=>'साइटमैप','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'साइटमैप कैश फ्लश किया गया। इसे साइटमैप URL पर अगली बार विजिट करने पर पुनः जेनरेट किया जाएगा।','Sitemap output'=>'साइटमैप आउटपुट','Sitemap settings saved.'=>'साइटमैप सेटिंग्स सहेजी गईं।','Sitemap URL'=>'साइटमैप URL','Size'=>'आकार','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'सामाजिक आइकन ब्लॉक शेयर: URLs: LF के बिल्ट-इन सोशल शेयर (SEO → सोशल शेयर) द्वारा हैं','Social Share'=>'सामाजिक शेयर','Social Share settings saved.'=>'सामाजिक शेयर सेटिंग्स सहेजी गईं।','Some link fixes failed.'=>'कुछ लिंक सुधार असफल रहे।','Some nav ref fixes failed.'=>'कुछ नेविगेशन संदर्भ सुधार असफल रहे।','Some part fixes failed.'=>'कुछ भाग सुधार असफल रहे।','Some parts could not be created.'=>'कुछ भाग नहीं बन सके।','Some templates could not be created.'=>'कुछ टेम्पलेट नहीं बन सके।','Some translations failed.'=>'कुछ अनुवाद असफल रहे।','source'=>'स्रोत','Source file not found.'=>'स्रोत फ़ाइल नहीं मिली।','Source lang'=>'स्रोत भाषा','Source language'=>'स्रोत भाषा','Source term'=>'स्रोत शब्द','Source title'=>'स्रोत शीर्षक','Standard'=>'मानक','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'मानक प्रत्येक सुविधा के अपने ट्यून किए गए तापमान का उपयोग करता है: अनुवाद T=0.2 (सटीक), त्वरित अनुवाद T=0.4, सामग्री निर्माता T=0.6 (रचनात्मक)। अन्य पूर्वसेट सभी सुविधाओं पर एकल स्थिर तापमान लागू करते हैं।','Start typing in any field to see model suggestions, or use the reference table below. Light and mid-tier Quality models (Haiku, GPT-4o mini, Gemini Flash) are fully sufficient for translation and content generation — flagship "max" models add cost with minimal quality gain for structured text.'=>'किसी भी फ़ील्ड में टाइप करना शुरू करें ताकि मॉडल सुझाव देखें, या नीचे दिए गए संदर्भ तालिका का उपयोग करें। लाइट और मिड-टियर क्वालिटी मॉडल (हाइकु, GPT-4o मिनी, जेमिनी फ्लैश) अनुवाद और सामग्री सृजन के लिए पूरी तरह से पर्याप्त हैं — फ्लैगशिप "मैक्स" मॉडल लागत जोड़ते हैं लेकिन संरचित टेक्स्ट के लिए न्यूनतम गुणवत्ता लाभ।','Status'=>'स्थिति','Status / Actions'=>'स्थिति / क्रियाएँ','Storytelling'=>'कहानी सुनाना','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'कानूनी, नियामक, चिकित्सा, या तकनीकी सामग्री के लिए सख्त संरक्षण मोड। जब चालू हो, तो हर AI सुविधा कम सैंपलिंग तापमान का उपयोग करती है और अपने सिस्टम प्रॉम्प्ट में नीचे दी गई परिशिष्ट जोड़ती है — शब्दावली, लेख संख्या, इकाइयां, ब्रांड नाम, और नियामक भाषा को शब्दशः संरक्षित किया जाता है, न कि परिभाषित।','Structured Outline'=>'संरचित रूपरेखा','Subdomain (de.example.com)'=>'उपडोमेन (de.example.com)','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'उपडोमेन मोड को आपकी वेब सर्वर को सभी भाषा उपडोमेन (जैसे de.example.com) को इस वर्डप्रेस इंस्टॉलेशन की ओर संकेत करने की आवश्यकता होती है। मोड बदलने के बाद, permalink नियमों को फ्लश करें और किसी भी कैश को साफ करें। यदि आपका होम URL www शामिल करता है (जैसे www.example.com), तो lf_base_domain फ़िल्टर का उपयोग करके बेस एपेक्स डोमेन सेट करें ताकि उपडोमेन सही ढंग से बनाए जा सकें।','Subdomain — de.example.com/'=>'उपडोमेन — de.example.com/','Submit this URL to Google Search Console alongside your main sitemap.'=>'अपने मुख्य साइटमैप के साथ इस URL को Google Search Console में सबमिट करें।','Submit to Reddit'=>'Reddit में सबमिट करें','Suggested meta description'=>'सुझावित मेटा विवरण','Suggested title'=>'सुझावित शीर्षक','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'समर्थित प्रदाता: Anthropic (Claude), OpenAI (GPT), Google (Gemini)। केवल एक प्रदाता सक्रिय है। सक्रिय प्रदाता का चयन सामान्य टैब पर करें। ','Suppressed: %s.'=>'दबाया गया: %s।','Switch to a post-name based structure in'=>'में पोस्ट-नाम आधारित संरचना पर स्विच करें','System'=>'सिस्टम','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, प्रति सुविधा','Tag'=>'टैग','Tags emitted'=>'टैग्स जारी किए गए','Target lang'=>'लक्ष्य भाषा','Target Language'=>'लक्ष्य भाषा','Target language'=>'लक्ष्य भाषा','Target term'=>'लक्ष्य शब्द','Target: 140–160 chars for optimal SERP display'=>'लक्ष्य: 140–160 अक्षर अनुकूल SERP प्रदर्शन के लिए','Technical'=>'प्राविधिक','Technical / Scientific'=>'तकनीकी / वैज्ञानिक','Technical / Scientific instructions'=>'तकनीकी / वैज्ञानिक निर्देश','Template "%s" already exists.'=>'टेम्पलेट "%s" पहले से मौजूद है।','Template "{expected}" does not exist — create it in the Site Editor first.'=>'टेम्पलेट "{expected}" मौजूद नहीं है — पहले इसे साइट संपादक में बनाएं।','Template has no content.'=>'टेम्पलेट में कोई सामग्री नहीं है।','Template mode'=>'टेम्प्लेट मोड','Template not found or not stored in the database.'=>'टेम्पलेट नहीं मिला या डेटाबेस में संग्रहीत नहीं है।','Template part "%s" already exists.'=>'टेम्पलेट भाग "%s" पहले से मौजूद है।','Template part has no content.'=>'टेम्पलेट भाग में कोई सामग्री नहीं है।','Template part not found or not stored in the database.'=>'टेम्पलेट भाग नहीं मिला या डेटाबेस में संग्रहीत नहीं है।','Template Parts'=>'टेम्प्लेट भाग','Templates'=>'टेम्प्लेट','Test connection'=>'कनेक्शन का परीक्षण करें','Testing…'=>'परीक्षण हो रहा है…','Text domain / locale'=>'टेक्स्ट डोमेन / स्थानीयकरण','Text to translate'=>'अनुवाद के लिए पाठ','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them.'=>'एपीआई प्रतिक्रिया कैश हर AI अनुरोध का कच्चा परिणाम संग्रहित करता है — अनुवाद, मेटा विवरण, अंश, और सामग्री निर्माण — इनपुट (सामग्री, भाषा जोड़ी, प्रदाता, मॉडल) के हैश द्वारा कुंजीबद्ध। प्रॉम्प्ट ट्यूनिंग के दौरान या जब आप हर अनुरोध को AI प्रदाता तक पहुंचाना चाहते हैं, तब अक्षम करें। अक्षम करने से कैश्ड प्रविष्टियों को हटाया नहीं जाता — पुनः सक्षम करने से वे पुनः प्राप्त हो जाते हैं।','The editor did not accept the content — please try again.'=>'संपादक ने सामग्री को स्वीकार नहीं किया — कृपया पुनः प्रयास करें।','The following directive is active in your virtual robots.txt:'=>'आपके वर्चुअल robots.txt में निम्नलिखित निर्देश सक्रिय है:','The lf-social-share mu-plugin is active.'=>'lf-social-share mu-plugin सक्रिय है।','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'lf-social-share mu-plugin सक्रिय है। Lingua Forge का इन-बिल्ट सोशल शेयर निष्क्रिय है — mu-plugin शेयर URL री-राइटिंग और JS क्रियाओं को संभालता है।','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'हल्का स्तर तेज़ मॉडल का उपयोग करता है जो ऊपर दिए गए मॉडल तालिका में कॉन्फ़िगर किया गया है (डिफ़ॉल्ट: Haiku / Flash)। यदि आप स्निपेट के लिए पूर्ण-पृष्ठ मोड जैसी अनुवाद सटीकता चाहते हैं तो गुणवत्ता पर स्विच करें।','The phrase as it appears in the source text.'=>'स्रोत पाठ में जैसा दिखाई देता है।','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'प्राथमिक भाषा हमेशा आपकी साइट के रूट पर सेवा की जाती है — पथ मोड में कोई URL उपसर्ग नहीं, उपडोमेन मोड में कोई भाषा उपडोमेन नहीं। अन्य सभी भाषाएँ या तो /lang/ पथ उपसर्ग (जैसे example.com/de/) का उपयोग करती हैं या भाषा उपडोमेन (जैसे de.example.com), URL संरचना सेटिंग के आधार पर।','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'SEO → Compatibility टैब लाइव डिटेक्शन स्थिति दिखाता है और प्रत्येक फीचर क्षेत्र के लिए LF क्या कर रहा है इसे स्पष्ट रूप से समझाता है।','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'शेयर URL हमेशा वर्तमान पृष्ठ को दर्शाता है — कोई मैनुअल URL प्रविष्टि आवश्यक नहीं। linguaforge_social_share_url फ़िल्टर आपको किसी भी सेवा के लिए हल किए गए URL को ओवरराइड करने की अनुमति देता है।','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'साइटमैप स्वचालित रूप से robots.txt में घोषित किया जाता है। सभी प्रमुख खोज इंजन — Google, Bing, Yandex — इसे robots.txt से खोजते हैं। कोई मैनुअल सबमिशन आवश्यक नहीं है।','The source page has no footnotes.'=>'स्रोत पृष्ठ में कोई फुटनोट नहीं है।','The upload failed — please try again.'=>'अपलोड विफल रहा — कृपया पुनः प्रयास करें।','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'WordPress कोर साइटमैप आपकी सभी सामग्री URL सूचीबद्ध करता है। LF साइटमैप खोज इंजनों को बताता है कि भाषा संस्करण एक-दूसरे से कैसे संबंधित हैं, XHTML:link hreflang विकल्पों के माध्यम से। दोनों को Google Search Console में सबमिट करें ताकि पूरी कवरेज हो सके।','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'ये फुटनोट स्रोत पृष्ठ से आते हैं और केवल संदर्भ के लिए यहां दिखाए गए हैं। इन्हें इस पृष्ठ में ब्लॉक संपादक का उपयोग करके जोड़ें।','This catalog is updated with each Lingua Forge release. Testing a connection in the API Keys tab also fetches the live model list from the provider and refreshes the suggestions above.'=>'यह कैटलॉग प्रत्येक Lingua Forge रिलीज के साथ अपडेट किया जाता है। API कीज़ टैब में कनेक्शन का परीक्षण करने से प्रदाता से लाइव मॉडल सूची भी प्राप्त होती है और ऊपर सुझाए गए सुझावों को ताज़ा किया जाता है।','This is a WooCommerce system page (Shop, Cart, Checkout, etc.). Its content is managed by WooCommerce — the score reflects structural signals only, not user-editable SEO content.'=>'यह WooCommerce सिस्टम पृष्ठ है (दुकान, कार्ट, चेकआउट, आदि)। इसकी सामग्री WooCommerce द्वारा प्रबंधित की जाती है — स्कोर केवल संरचनात्मक संकेतों को दर्शाता है, न कि उपयोगकर्ता-संपादित SEO सामग्री।','This is the source page. Footnotes are edited directly in the block editor.'=>'यह स्रोत पृष्ठ है। फुटनोट सीधे ब्लॉक संपादक में संपादित किए जाते हैं।','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'यह कुंजी वर्तमान में एक सर्वर %s द्वारा प्रदान की जा रही है और इसे यहाँ से नहीं हटाया जा सकता। इसे ओवरराइड करने के लिए ऊपर एक नई कुंजी दर्ज करें।','This language is protected and cannot be uninstalled.'=>'यह भाषा सुरक्षित है और अनइंस्टॉल नहीं की जा सकती।','This language matches the WordPress instance locale and cannot be uninstalled.'=>'यह भाषा WordPress इंस्टेंस लोकल के साथ मेल खाती है और अनइंस्टॉल नहीं की जा सकती।','Tier'=>'स्तर','Tip: to reset a model to the built-in default, clear the field and save.'=>'टिप: एक मॉडल को डिफ़ॉल्ट में रीसेट करने के लिए, फ़ील्ड साफ़ करें और सहेजें।','Title'=>'शीर्षक','Title 15 pts · Meta description 20 pts · Word count 15 pts · Headings 20 pts · Images 10 pts · Links 10 pts. Title SERP limit 60 chars; meta 120–210 chars; word count warns below 300, fails below 100; H2 required; internal links required.'=>'शीर्षक 15 अंक · मेटा विवरण 20 अंक · शब्द गणना 15 अंक · शीर्षक 20 अंक · छवियां 10 अंक · लिंक 10 अंक। शीर्षक SERP सीमा 60 वर्ण; मेटा 120–210 वर्ण; शब्द गणना नीचे 300 चेतावनी, 100 से नीचे असफल; H2 आवश्यक; आंतरिक लिंक आवश्यक।','Title is %1$d chars — may be truncated in SERPs (aim for under %2$d).'=>'शीर्षक %1$d वर्ण है — SERPs में काटा जा सकता है (100 से कम का लक्ष्य रखें %2$d)।','Title is only %d chars — aim for at least 10 characters.'=>'शीर्षक केवल %d वर्ण है — कम से कम 10 वर्णों का लक्ष्य रखें।','Title scoring rules (all profiles): fail if empty; warn if fewer than 10 characters; warn if only one word; warn if longer than the profile\'s SERP limit (60 chars for Blog, 70 for Product/Landing); ok if at least 10 characters, at least 2 words, and within the SERP limit.'=>'शीर्षक स्कोरिंग नियम (सभी प्रोफाइल): यदि खाली हो तो असफल; यदि 10 वर्णों से कम हो तो चेतावनी; यदि केवल एक शब्द हो तो चेतावनी; यदि प्रोफ़ाइल की SERP सीमा (ब्लॉग के लिए 60 वर्ण, उत्पाद/लैंडिंग के लिए 70) से अधिक हो तो चेतावनी; यदि कम से कम 10 वर्ण, कम से कम 2 शब्द, और SERP सीमा के भीतर हो तो ठीक।','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'कस्टम एन्क्रिप्शन सीक्रेट का उपयोग करने के लिए (डेराइव्ड wp_salt मान के बजाय), इसे wp-config.php में जोड़ें:','Today'=>'आज','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'टोकन खपत फीचर, प्रदाता, और मॉडल द्वारा रोल की गई। हर सफल AI कॉल पर रिकॉर्ड किया जाता है; टेस्ट कनेक्शन पिंग को बाहर रखा गया है ताकि वे कुल को प्रभावित न करें।','Tone'=>'स्वर','tone'=>'स्वर','Tone:'=>'स्वर:','Too many AI requests. Please retry in %d seconds.'=>'बहुत अधिक AI अनुरोध। कृपया %d सेकंड में पुनः प्रयास करें।','Total'=>'कुल','Total tokens'=>'कुल टोकन','Translate'=>'अनुवाद करें','Translate / Revise'=>'अनुवाद / संशोधन','Translate / Revise block'=>'संशोधन ब्लॉक','Translate all'=>'सभी का अनुवाद करें','Translate chunk'=>'टुकड़ा अनुवाद करें','Translate Content'=>'सामग्री का अनुवाद करें','Translate missing'=>'लापता अनुवाद करें','Translate page…'=>'पृष्ठ का अनुवाद करें…','Translated content'=>'अनुवादित सामग्री','Translated Names'=>'अनुवादित नाम','Translated title'=>'अनुवादित शीर्षक','Translated to:'=>'अनुवादित:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'अनुवादित। साइट संपादक में समीक्षा करें — आंतरिक लिंक, नेविगेशन URL, और टेम्प्लेट स्लग स्वचालित रूप से अपडेट नहीं होते हैं।','Translating…'=>'अनुवाद हो रहा है…','Translation'=>'अनुवाद','Translation Caching'=>'अनुवाद कैशिंग','Translation found but permalink could not be generated'=>'अनुवाद मिला लेकिन permalink उत्पन्न नहीं किया जा सका','Translation Limits'=>'अनुवाद सीमाएँ','Translation Limits & Behavior'=>'अनुवाद सीमाएँ और व्यवहार','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'अनुवाद सीमाएँ: नियंत्रित करें कि कौन से उपयोगकर्ता भूमिकाएँ AI अनुवाद को ट्रिगर कर सकती हैं, और मासिक टोकन बजट सेट करें। बजट से अधिक होने पर AI कॉल स्थगित हो जाती हैं जब तक कि महीना पुनः शुरू न हो जाए।','Translation Memory'=>'अनुवाद स्मृति','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'अनुवाद स्मृति कैश Content hash, भाषा जोड़ी, प्रदाता, और मॉडल के आधार पर AI परिणामों को कैश करती है। एक पोस्ट को संपादित करने से कैश प्रविष्टि अमान्य हो जाती है ताकि अगली अनुवाद कॉल ताजा परिणाम प्राप्त कर सके।','Translation Memory cleared. %d cached block was removed.'=>'अनुवाद स्मृति साफ़ कर दी गई। %d कैश्ड ब्लॉक हटा दिया गया।' . "\0" . 'अनुवाद स्मृति साफ़ कर दी गई। %d कैश्ड ब्लॉक हटा दिए गए।','Translation Memory setting saved.'=>'अनुवाद स्मृति सेटिंग सहेजी गई।','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'अनुवाद स्मृति: प्रत्येक सामग्री हैश के लिए पूर्ण अनुवादित पोस्ट को संग्रहित करता है। जब आप चाहते हैं कि सभी पोस्ट का पुनः अनुवाद किया जाए, तो इसे साफ़ कर दें, चाहे उनके सामग्री में परिवर्तन हुआ हो या नहीं।','Translation workflow'=>'अनुवाद कार्यप्रवाह','Translation, Content Generator'=>'अनुवाद, सामग्री निर्माता','Treat H2 as H1 equivalent'=>'H2 को H1 के समकक्ष मानें','Type'=>'प्रकार','Uli Hake'=>'उली हाके','Unexpected provider error (HTTP %d).'=>'अप्रत्याशित प्रदाता त्रुटि (HTTP %d)।','Uninstall %s'=>'अ uninstall %s','Uninstall Behaviour'=>'अस्थायी व्यवहार','Uninstall setting saved.'=>'अस्थायी व्यवहार सेटिंग सहेजी गई।','unknown error'=>'अज्ञात त्रुटि','Unknown provider.'=>'अज्ञात प्रदाता।','Unknown search engine.'=>'अज्ञात खोज इंजन।','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'Hreflang के विपरीत — जहां LF हमेशा अन्य प्लगइन्स को ओवरराइड करता है क्योंकि वे आपकी बहुभाषी कॉन्फ़िगरेशन को नहीं जान सकते — Open Graph अलग है: Yoast, Rank Math, और समान प्लगइन्स पहले से ही आपके सामग्री के लिए सही OG टैग आउटपुट करते हैं। उन्हें डुप्लिकेट करने का कोई मूल्य नहीं है। ऑटो मोड में, LF सक्रिय SEO प्लगइन्स का पता लगाता है और केवल वही जोड़ता है जो वे प्रदान नहीं कर सकते: og:locale (वर्तमान भाषा) और og:locale:alternate (सभी अन्य कॉन्फ़िगर की गई भाषाएँ)।','Unlimited'=>'असीमित','Up'=>'ऊपर','Upload .mo file'=>'.mo फ़ाइल अपलोड करें','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'विशिष्ट स्थानीयकरण के लिए तृतीय-पक्ष प्लगइन स्ट्रिंग्स को ओवरराइड करने के लिए संकलित .mo फ़ाइलें अपलोड करें — उदाहरण के लिए, एक कस्टम VikBooking अनुवाद जो "कमरा" के बजाय "अपार्टमेंट" का उपयोग करता है। फ़ाइलें WordPress नामकरण सम्मेलन का पालन करनी चाहिए: {textdomain}-{locale}.mo (जैसे vikbooking-ca.mo)। इन्हें अपलोड्स फ़ोल्डर में संग्रहित किया जाता है और प्लगइन अपडेट के दौरान भी रहते हैं।','Upload Override'=>'ओवरराइड अपलोड करें','URL could not be mapped to a post — check the link target exists'=>'URL को पोस्ट से मैप नहीं किया जा सका — लिंक लक्ष्य मौजूद है या नहीं जांचें','URL structure'=>'URL संरचना','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'URL संरचना: पथ-प्रारंभ मोड (उदाहरण.com/de/) में कोई सर्वर परिवर्तन आवश्यक नहीं है। उपडोमेन मोड (de.example.com) में वाइल्डकार्ड DNS रिकॉर्ड, वाइल्डकार्ड SSL प्रमाणपत्र, और वेब सर्वर कॉन्फ़िगरेशन परिवर्तन की आवश्यकता होती है — देखें सर्वर सेटअप गाइड।','URL to enter'=>'प्रविष्ट करने के लिए URL','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'जब उपलब्ध हो तो नेटिव शेयर का उपयोग करें; क्लिपबोर्ड कॉपी परFallback। "शेयर" बटनों के लिए अनुशंसित डिफ़ॉल्ट।','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'इस पृष्ठ के ऊपर टैब का उपयोग करके प्रत्येक क्षेत्र को कॉन्फ़िगर करें। राउटर टैब में परिवर्तन तुरंत प्रभावी होते हैं; AI कुंजी और मॉडल सेटिंग्स में परिवर्तन अगले AI अनुरोध पर लागू होते हैं।','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'प्रति भाषा जोड़ी के लिए उपयोगकर्ता-प्रबंधित शब्दावली तालिका। प्रविष्टियों को अनुवाद प्रणाली प्रॉम्प्ट में जोड़ा जाता है ताकि AI लगातार वांछित शब्दों का उपयोग करे — क्षेत्रीय शब्दावली ("kWp", "PPA", "interconnection point"), ब्रांड नाम जिन्हें अनुवादित नहीं किया जाना चाहिए, और मानकीकृत नियमावली वाक्यांश। दोनों भाषा क्षेत्रों को वैकल्पिक है: "स्रोत भाषा" को खाली छोड़ें ताकि यह प्रविष्टि किसी भी भाषा से अनुवाद करने पर लागू हो; "लक्ष्य भाषा" को खाली छोड़ें ताकि यह सभी लक्षित भाषाओं पर एक साथ लागू हो।','Using custom meta description.'=>'कस्टम मेटा विवरण का उपयोग कर रहा है।','Using LF AI meta description.'=>'LF AI मेटा विवरण का उपयोग कर रहा है।','Value source'=>'मूल स्रोत','Version'=>'संस्करण','View'=>'देखें','View built-in default'=>'निर्मित डिफ़ॉल्ट देखें','View current robots.txt'=>'वर्तमान robots.txt देखें','View details'=>'विवरण देखें','View Lingua Forge details'=>'लिंगुआ फोर्ज विवरण देखें','Visit plugin site'=>'प्लगइन साइट पर जाएं','Warning:'=>'चेतावनी:','WcPageBridge active'=>'WcPageBridge सक्रिय','WebSite'=>'वेबसाइट','WebSite — front page / blog index'=>'वेबसाइट — होम पेज / ब्लॉग सूचकांक','What LF provides — and collision avoidance'=>'LF क्या प्रदान करता है — और टकराव से बचाव','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'LF क्या प्रदान करता है: हर कॉन्फ़िगर की गई भाषा के लिए hreflang टैग, Open Graph और Twitter Card टैग्स with og:locale और og:locale:alternate, Schema.org JSON-LD with inLanguage एनोटेशन, और /lf-sitemap.xml पर एक समर्पित बहुभाषी साइटमैप जिसमें सभी अनुवाद समूहों के लिए xhtml:link विकल्प प्रविष्टियां हैं।','When another SEO plugin is installed'=>'जब कोई अन्य SEO प्लगइन इंस्टॉल हो','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'जब डिबग लॉगिंग सक्षम होती है (नीचे टॉगल के माध्यम से या wp-config.php में LINGUAFORGE_AI_DEBUG को परिभाषित करके), अनुवाद और FSE टेम्प्लेट अनुवाद सुविधाएँ अपने कच्चे AI प्रॉम्प्ट और प्रतिक्रियाओं को समस्या निवारण के लिए डिस्क पर लिखती हैं। इस अनुभाग का उपयोग उस आउटपुट की निगरानी करने के लिए करें और जब आप आवश्यक हो तो इसे साफ़ करें — फ़ाइलें बड़े पृष्ठों पर जल्दी बढ़ सकती हैं। टारगेट डायरेक्टरी को linguaforge_debug_dir फ़िल्टर के माध्यम से कॉन्फ़िगर करें।','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'जब सक्षम हो, तो पहली बार आने वाले आगंतुक जिनके पास कोई भाषा कुकी नहीं है और URL में कोई भाषा उपसर्ग नहीं है, उन्हें सबसे मिलते-जुलते भाषा संस्करण पर पुनः निर्देशित किया जाता है। यदि ब्राउज़र की पसंदीदा भाषा सक्रिय राउटर भाषाओं में से नहीं है, तो पुनः निर्देशित नहीं किया जाता है। जब कोई आगंतुक स्विचर के माध्यम से एक भाषा चुनता है, तो कुकी प्राथमिकता लेती है और भविष्य की सभी यात्राओं पर ब्राउज़र हेडर को नजरअंदाज किया जाता है।','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'सक्रिय होने पर, Lingua Forge उत्पाद पृष्ठों पर निम्नलिखित अतिरिक्त मेटा टैग्स आउटपुट करता है: og:type=product, og:price:amount, og:price:currency, og:availability, और उनके product: namespace के समकक्ष Facebook Catalog द्वारा उपयोग किए जाते हैं।','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'सक्रिय होने पर, साइटमैप URL स्वचालित रूप से robots.txt में घोषित किया जाता है और अनुवादित सामग्री सहेजी जाने पर कैश को ताजा किया जाता है।','When the Blog profile requires an H2 and none is found, the analyser first checks for H3 subheadings before issuing a warning. Accordion and Details blocks default to H3 for their headers; those H3s are accepted as valid structure and produce an ok result, not a warning.'=>'जब ब्लॉग प्रोफाइल में H2 की आवश्यकता हो और कोई न हो, तो विश्लेषक पहले H3 उपशीर्षकों की जांच करता है इससे पहले कि चेतावनी जारी करे। ऐकार्डियन और डिटेल्स ब्लॉक अपने हेडर के लिए डिफ़ॉल्ट रूप से H3 का उपयोग करते हैं; ये H3 मान्य संरचना के रूप में स्वीकार किए जाते हैं और एक ठीक परिणाम उत्पन्न करते हैं, न कि चेतावनी।','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'जब Yoast SEO, Rank Math, All in One SEO, या SEOPress सक्रिय हो, तो Lingua Forge स्वचालित रूप से उनके hreflang आउटपुट को फ़िल्टर के माध्यम से दबाता है। सामान्य SEO प्लगइन्स एकल-भाषा URL संरचना पर आधारित hreflang बनाते हैं और आपकी बहुभाषी रूटिंग कॉन्फ़िगरेशन को ध्यान में नहीं रख सकते; LF का आउटपुट हमेशा सही होता है।','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'पूर्ण-पृष्ठ अनुवाद के लिए कौन सा मॉडल स्तर उपयोग करें। गुणवत्ता ऊपर दिए गए Models तालिका में कॉन्फ़िगर किए गए मॉडल का उपयोग करता है और सटीक, लंबी-फॉर्म अनुवाद के लिए अनुशंसित है। केवल यदि गति या लागत प्राथमिकता है और सामग्री छोटी है तो ही Light पर स्विच करें।','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'सक्रिय रहने पर, mu-plugin मूल OG सेट को संभालता है और LF केवल लोकल टैग्स (ऑटो मोड) को उत्सर्जित करता है। इसे हटाने से LF स्वचालित रूप से पूर्ण OG मोड में स्विच कर जाता है।','WooCommerce'=>'WooCommerce','WooCommerce is not active.'=>'WooCommerce सक्रिय नहीं है।','WooCommerce page translations'=>'WooCommerce पृष्ठ अनुवाद','WooCommerce product price'=>'WooCommerce उत्पाद मूल्य','WooCommerce SEO settings saved.'=>'WooCommerce SEO सेटिंग्स सहेजी गईं।','WooCommerce store currency'=>'WooCommerce स्टोर मुद्रा','WooCommerce system pages (Shop, Cart, Checkout, My Account) are excluded — their content is managed by WooCommerce and cannot be improved through SEO edits.'=>'WooCommerce सिस्टम पृष्ठ (दुकान, कार्ट, चेकआउट, मेरा खाता) को बाहर रखा गया है — उनकी सामग्री WooCommerce द्वारा प्रबंधित की जाती है और SEO संपादन के माध्यम से सुधारा नहीं जा सकता।','WooCommerce version'=>'WooCommerce संस्करण','Word count'=>'शब्द गणना','WordPress version'=>'वर्डप्रेस संस्करण','WP core canonical active (hreflang disabled)'=>'WP कोर कैनोनिकल सक्रिय (hreflang अक्षम)','WP instance language'=>'WP इंस्टेंस भाषा','WP-CLI reference'=>'WP-CLI संदर्भ','Write AI prompts and responses to disk for troubleshooting'=>'समस्या निवारण के लिए AI प्रॉम्प्ट और प्रतिक्रियाएँ डिस्क पर लिखें','XML Sitemap'=>'XML साइटमैप','Yes'=>'हाँ','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'आप कुंजी को स्थिरांक या पर्यावरण चर के रूप में भी परिभाषित कर सकते हैं (जैसे wp-config.php में)। ये स्रोत स्वचालित रूप से तब उपयोग किए जाते हैं जब कोई डेटाबेस कुंजी संग्रहीत नहीं होती।','You do not have permission to manage these settings.'=>'आपके पास इन सेटिंग्स का प्रबंधन करने की अनुमति नहीं है।','You do not have permission to read this post.'=>'आपके पास इस पोस्ट को पढ़ने की अनुमति नहीं है।','{n} stale path(s)'=>'{n} पुराना पथ(आम','~%d min read'=>'~%d मिनट पढ़ें' . "\0" . '~%d मिनट पढ़ें','— AI features are disabled.'=>'— AI सुविधाएँ अक्षम हैं।','— Any source language —'=>'— कोई भी स्रोत भाषा —','— Any target language —'=>'— कोई भी लक्ष्य भाषा —','— Any target —'=>'— कोई भी लक्ष्य —','— Any —'=>'— कोई भी —','— Auto-detect —'=>'— स्वचालित पता लगाना —','— auto-detect —'=>'— स्वचालित पता लगाएँ —','— Deferred to plugin'=>'— प्लगइन को सौंपा गया','— Disabled'=>'— अक्षम','— Not detected'=>'— पता नहीं चला','— select a language —'=>'— एक भाषा चुनें —','← Back'=>'← वापस','↑ Detected from current post'=>'↑ वर्तमान पोस्ट से पता चला','→ Locale tags only (manual setting)'=>'→ केवल लोकल टैग (मैनुअल सेटिंग)','→ Locale tags only — deferring base OG to plugin'=>'→ केवल लोकल टैग — बेस OG को प्लगइन पर छोड़ना','↺ Re-translate'=>'↺ पुनः अनुवाद','↺ Refine'=>'↺ परिष्कृत करें','↺ Refresh'=>'↺ ताज़ा करें','↺ Refresh AI Analysis'=>'↺ AI विश्लेषण ताज़ा करें','↺ Refreshing…'=>'↺ ताज़ा हो रहा है…','⚠ Borderline'=>'⚠ सीमा रेखा','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ कोई <strong>{lang}</strong> पोस्ट नहीं मिली। सुनिश्चित करें कि सभी अनुवादित पोस्ट में उनकी भाषा मेटा <strong>{lang}</strong> पर सेट हो।','⚠ No changes'=>'⚠ कोई परिवर्तन नहीं','⚠ No changes — re-scan?'=>'⚠ कोई परिवर्तन नहीं — पुनः स्कैन करें?','✅ Fixed ({n})'=>'✅ ठीक किया ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ <strong>{lang}</strong> के लिए कोई टूटा लिंक या टेम्प्लेट मेल नहीं मिला। स्कैन किए गए <strong>{scanned}</strong> पोस्ट और पृष्ठ — सभी जांच पास। टेम्प्लेट भाग लिंक (हेडर, फुटर, साइडबार) यहां शामिल नहीं हैं — उन्हें अलग से जांचने के लिए फिक्स टेम्प्लेट पार्ट्स बटन का उपयोग करें।','✅ Template fixed'=>'✅ टेम्पलेट ठीक किया गया','✓ %s notified successfully.'=>'✓ %s सफलतापूर्वक सूचित किया गया।','✓ Active'=>'✓ सक्रिय','✓ Active at /lf-sitemap.xml'=>'✓ /lf-sitemap.xml पर सक्रिय','✓ Active — %d URL entry with language alternates'=>'✓ सक्रिय — %d URL प्रविष्टि के साथ भाषा विकल्प' . "\0" . '✓ सक्रिय — %d URL प्रविष्टियों के साथ भाषा विकल्प','✓ Active — full OG + Twitter Cards'=>'✓ सक्रिय — पूर्ण OG + ट्विटर कार्ड','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ सक्रिय — केवल लोकल टैग (og:locale, og:locale:alternate)','✓ All parts created.'=>'✓ सभी भाग बनाए गए।','✓ All templates created.'=>'✓ सभी टेम्पलेट बनाए गए।','✓ All translated.'=>'✓ सभी अनुवादित।','✓ Configured'=>'✓ कॉन्फ़िगर किया गया','✓ Connection OK'=>'✓ कनेक्शन ठीक है','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ सामग्री बनाई गई — समीक्षा, संशोधन और लागू करने के लिए ओवरले देखें।','✓ Done'=>'✓ पूरा हुआ','✓ Enabled'=>'✓ सक्षम','✓ Good length'=>'✓ अच्छा लंबाई','✓ Hreflang active'=>'✓ Hreflang सक्रिय','✓ In safe storage'=>'✓ सुरक्षित संग्रह में','✓ Language installed.'=>'✓ भाषा स्थापित।','✓ LF outputs'=>'✓ LF आउटपुट','✓ LF outputs Article / WebPage / WebSite'=>'✓ LF आउटपुट लेख / वेबपेज / वेबसाइट','✓ LF outputs full OG + Twitter Cards'=>'✓ सक्रिय — पूर्ण OG + ट्विटर कार्ड','✓ LF outputs — plugin hreflang suppressed'=>'✓ LF आउटपुट — प्लगइन hreflang दबाया गया','✓ Links fixed.'=>'✓ लिंक ठीक किए गए।','✓ Nav refs fixed.'=>'✓ नेविगेशन संदर्भ ठीक किए गए।','✓ Parts fixed.'=>'✓ भाग ठीक किए गए।','✓ Pattern translated.'=>'✓ पैटर्न का अनुवाद किया गया।','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ भौतिक robots.txt मिला। LF का साइटमैप निर्देश मौजूद है।','✓ Refined — review the updated draft above.'=>'✓ सुधारा गया — ऊपर दिए गए मसौदे की समीक्षा, संशोधन और लागू करने के लिए देखें।','✓ Translation saved'=>'✓ अनुवाद सहेजा गया','✓ WP core canonical removed'=>'✓ WP कोर कैनोनिकल हटा दिया गया','✗ %s ping failed. The sitemap URL is still announced in robots.txt — the search engine will discover it on its next crawl.'=>'✗ %s पिंग विफल। साइटमैप URL अभी भी robots.txt में घोषित है — खोज इंजन इसे अपने अगले क्रॉल पर खोज लेगा।','✗ Disabled'=>'✗ अक्षम','✗ Error:'=>'✗ त्रुटि:','✗ Failed:'=>'✗ असफल:,','✗ Not configured'=>'✗ कॉन्फ़िगर नहीं किया गया','✗ Too long'=>'✗ बहुत लंबा','✗ Too short'=>'✗ बहुत छोटा','❌ Failed'=>'❌ विफल','📄 Wrong template'=>'📄 गलत टेम्पलेट','📍 Stale path (page moved)'=>'📍 पुराना पथ (पृष्ठ स्थानांतरित)']];
